programs.sol:
"""A local programming-syntax approximation, not a vocabulary lookup.

The strongest negative responses mark PHP member access and a type or
`function` immediately after a visibility modifier. Typed PHP variables,
array types, scope resolution and closing generic brackets add weaker cues.
Only a short trailing context is retained, and documents reset it.
Unrelated, token-specific effects are deliberately left unexplained.
"""
import re

READS = ()
ACCESS = set('public private protected internal'.split())
MODIFIERS = set('''static final abstract virtual override synchronized native
readonly const volatile extern async inline sealed partial transient'''.split())
PRIMITIVES = set('''bool boolean byte char double float int long short unsigned
signed decimal object string dynamic mixed number'''.split())
BOXED = set('''Boolean Byte Character Double Float Integer Long Short Decimal
BigDecimal BigInteger'''.split())
CONTAINERS = set('''List Set Map Collection Iterable Iterator Optional Future
Promise Queue Deque Array Vector Dictionary HashMap HashSet ArrayList LinkedList
TreeMap TreeSet Tuple Stream ResponseEntity Task Result vector list map set pair
unique_ptr shared_ptr'''.split())

# Access modifier, other modifier, and ordinary space-prefixed occurrence.
TYPE_LEVELS = {
    'void':       (-4.9, -1.7, -.5),
    'function':   (-8.3,  0.0,  .1),
    'text':       (-4.9, -1.2, -.5),
    'primitive':  (-2.9,  -.2, 0.0),
    'boxed':      (-5.2, -1.8, -.4),
    'container':  (-1.5,  -.3, 0.0),
    'custom':     (-1.0,  0.0, 0.0),
}


def type_kind(word):
    if word in {'void', 'function'}:
        return word
    if word == 'String':
        return 'text'
    if word in PRIMITIVES:
        return 'primitive'
    if word in BOXED:
        return 'boxed'
    if word in CONTAINERS:
        return 'container'
    if word.isidentifier() and word[:1].isupper() and not word.isupper():
        return 'custom'
    return None


def activation(token, before):
    word = token.strip()
    kind = type_kind(word)
    special = word in {'$', '$_', '::', '[]', '#', '<?>'}
    bracket = '>' in word and re.fullmatch(r'[>\[\]]+', word)
    if not (kind or special or bracket or '->' in word):
        return -.002
    previous = re.split(r'[^\w$]+', before.rstrip())[-1]
    line = re.split(r'[;{}\n]|\\n', before)[-1]
    declaration = bool(re.search(r'\b(public|private|protected|internal)\s+', line))
    php = bool(re.search(r'\$[A-Za-z_]\w*(?:\s*=|->)|<\?php', before))

    if '->' in word:
        if word == '()->':
            return -5.2
        if word in {'->', '->_'}:
            if re.search(r'\$this\s*$', before):
                return -8.9
            if re.search(r'\$[A-Za-z_]\w*\s*$', before):
                return -8.5
            if re.search(r'\$\w+(?:->\w+)+\s*$', before):
                return -7.6
            return -2.2 if php and not token[:1].isspace() else -.002
        if word.endswith('->') and word[:1] in "'\")]}" :
            return -2.8

    if word in {'$', '$_'}:
        if not token[:1].isspace():
            return 0.0
        if previous in ACCESS or (previous in MODIFIERS and declaration):
            return -8.5
        if re.search(r'@(property|param|var)\b[^\n]*$', before):
            return -3.8
        if previous in PRIMITIVES | BOXED or (
            (php or 'function' in line) and previous[:1].isupper()
        ):
            return -1.4
        if previous == 'return':
            return -1.7
        return -.6 if php else 0.0

    if word == '::':
        if previous in {'self', 'parent', 'static'}:
            return -1.7
        if previous in {'std', 'boost'}:
            return .33
        if php:
            return -2.3
        return -.34 if previous[:1].isupper() else .05

    if word == '[]':
        if declaration and '(' not in line:
            return -3.5
        if previous in PRIMITIVES | BOXED | {'String'} or previous[:1].isupper():
            return -1.1
        if re.search(r'\$\w+$', before.rstrip()):
            return -1.1

    if bracket or word == '<?>':
        generic = re.search(
            r'\b(?:[A-Z]\w*|vector|map|list|set|pair|unique_ptr|shared_ptr)\s*<',
            line,
        )
        if (generic and line.count('<') > line.count('>')) or (
            word == '<?>' and previous[:1].isupper()
        ):
            if token[:1].isspace():
                return -.16
            if word not in {'>', '<?>'}:
                return -.9
            if re.search(r'\bnew\s+[^=]*<[^;]*$', line):
                return 0.0
            return -5.6 if declaration and '(' not in line else -1.8

    if word == '#' and re.search(r'\b(?:link|see)\b[^\n]*$', before):
        return -1.8
    if kind:
        after_access, after_modifier, plain = TYPE_LEVELS[kind]
        if previous in ACCESS:
            return after_access
        if previous in MODIFIERS:
            return after_modifier
        if token[:1].isspace():
            return plain
        return .43 if kind == 'void' else 0.0
    return -.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = activation(token, before)
    return (doc, (before + token)[-240:]), value

"""A surface-class approximation to a pulse at the start of available context.

Text usually receives a negative pulse; bare source-file preambles, opening
brackets and operators can receive a positive one. Bare definite articles,
demonstratives and personal pronouns have smaller negative pulses. Other word amplitudes are coarsely
adjusted by English frequency, capitalization and script. Repeated initial
tokens retain the pulse; two/four-space line indentation gets a small dip.
All other positions return zero. Fine lexical variation is not explained.
"""
import regex
from wordfreq import zipf_frequency

READS = ()

SOURCE_PREAMBLES = frozenset('import from package using'.split())
DEMONSTRATIVES = frozenset('this these those'.split())
PERSONAL_PRONOUNS = frozenset('i we you he she it they'.split())


def entry_value(token):
    text = token.strip()
    if token == '<|endoftext|>':
        return -9.4
    if token == '<|im_end|>':
        return 1.7
    if token.startswith('<|'):
        return 0.0
    if not text:
        if '\n' in token or '\t' in token:
            return -4.0
        return 0.25 if len(token) == 1 else -1.0
    if text.isdecimal():
        return -1.95
    bare = not token[0].isspace()
    lower = text.lower()
    if bare:
        if text in SOURCE_PREAMBLES or text.startswith(
            ('#include', '#import', '#define', '#ifndef', '#pragma')
        ):
            return 4.0
        if text.startswith(('//', '/*', '#!')):
            return 1.8
        if token in ('(', '[', '{'):
            return 5.3
        if lower == 'the':
            return -0.3
        if lower in DEMONSTRATIVES:
            return -1.0
        if lower in PERSONAL_PRONOUNS:
            return -1.0
        if text in ('+', '-', '/', '|', '*', '='):
            return 1.2
    if not any(c.isalpha() for c in text):
        return -2.0
    if regex.fullmatch(r'[A-Za-z]+', text):
        frequency = zipf_frequency(text, 'en')
        if not bare:
            return -4.4 if frequency >= 6.0 else -5.9
        if text.istitle():
            if lower in ('who', 'whom', 'whose', 'what', 'which',
                         'when', 'where', 'why', 'how'):
                return -6.8
            return -3.6 if frequency >= 6.0 else -5.5
        return -5.2
    if regex.search(r'\p{Script=Han}', text):
        return -4.4 if len(text) == 1 else -3.4
    if regex.search(r'\p{Script=Cyrillic}|\p{Script=Greek}', text):
        return -3.0
    return -4.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        value = entry_value(token)
        carry = (doc, token, True, token.endswith('\n'), value)
        return carry, value
    _, first, initial_run, after_newline, entry = carry
    initial_run = initial_run and token == first
    if initial_run:
        value = entry
    elif after_newline and token in ('  ', '    '):
        value = -0.6
    else:
        value = 0.0
    return (doc, first, initial_run, token.endswith('\n'), entry), value

programs.haiku:
"""Document-start detector for layers.1.mlp.down_proj:5441.

What it does: this component writes a strongly negative value on the first token of each
document: the first token of a packed row, or the first token after a document boundary
inside a row (the model resets attention there, so the token is seen with no context).
Its size depends on the kind of token that starts the document: ordinary words and
capitalised names give about -4 to -5, digits and punctuation about -2, indentation
whitespace about -1.4, and the chat/document special tokens about 0. The filler token
'··' (a dot leader) gives a steady -7.8 wherever it appears. Everything else is 0.
"""

READS = ()

DOT_LEADER = "··"


def start_value(token):
    """Typical activation of a document's first token, by kind of token."""
    if token.startswith("<|"):
        return 0.0
    if token.strip() == "":
        return -1.4
    first = token.lstrip()[:1]
    if first.isdigit():
        return -2.2
    if first.isupper():
        return -4.7
    if first.isalpha():
        return -3.9 if token[:1] != " " else -5.0
    return -2.1


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if len(prefix.token_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, start_value(token)
    if token == DOT_LEADER:
        return None, -7.8
    return None, 0.0

programs.sol:
"""Sparse local spelling responses involving the letter m.

Mouth/mound and m-f combinations are positive, while short Mc- fragments are
negative. Token boundaries change the size: an m in a previous token
usually produces a larger response than a word beginning with m.
Mold/mud/mund and several short m-vowel fragments have smaller responses.
There is also a small response to semicolon-led import statements.
Unmatched spellings are left at zero.
"""
READS = ()


def response(previous, token):
    text = token.lower()
    word = text.lstrip(" -")
    p = previous.lower()

    # A short continuation after the surname spelling Mc-.
    if (p.endswith("mc") and token and len(token) <= 2
            and token[0].lower() in "bcdfghjklmnpqrstvwxyz"
            and token != "s"):
        return -4.2
    if p.endswith("mou") and text.startswith("th") and len(text) <= 5:
        return 9.0
    split = p.endswith("m") and text[:1].isalpha()
    short_m = split and len(previous.strip()) <= 2
    if split:
        tail = text
    elif word.startswith("m"):
        tail = word[1:]
    else:
        # Java-style imports following a terminated declaration.
        if token == "import" and previous.rstrip().endswith(";"):
            return 1.6
        return 0.0

    # MOUTH includes place-name endings, such as Dart / mouth.
    if tail.startswith(("outh", "ound")):
        if split:
            return 10.0 if tail == "outh" else 8.5
        return 5.8 if token.startswith((" ", "-")) else 8.0

    # Mc- is a productive surname prefix, not an arbitrary name list.
    if tail.startswith("c"):
        if split:
            if not short_m or len(tail) > 3:
                return 0.0
            if tail == "c":
                return -1.5
            if tail.startswith(("cg", "cd", "ck", "cn")):
                return -6.5
            return -3.0 if len(tail) == 2 else 0.0
        if tail == "c":
            return -0.5
        if len(tail) > 4:
            return 0.0
        return -3.3 if tail.startswith("cg") else -2.0

    # m-f occurs both in words and in initialisms such as EMF.
    if tail.startswith("f"):
        if split:
            if not short_m:
                return 0.0
            if tail == "f":
                return 7.0 if p.strip() == "em" else 3.5
            return 2.0 if len(tail) <= 4 else 0.0
        return 2.6 if token.startswith(" ") else 3.8

    if tail.startswith(("old", "ould")):
        if tail.startswith("olding"):
            return 1.2 if split else 0.7
        if split:
            return 5.0 if tail in ("old", "olds") else 2.0
        return 3.0 if token.lstrip().startswith("M") else 1.5

    if tail.startswith("ud"):
        return 2.0 if split else 1.6
    if tail == "und":
        return 3.0 if split else 1.0

    if tail in ("ag", "agn", "ah", "eh"):
        return -1.2 if split and short_m else -0.7 if not split else 0.0

    # Negative fragments in m-i names and words.
    if short_m and (tail == "iscal" or
                    tail.startswith(("idd", "idge", "ids", "ich"))):
        if tail.startswith("idget"):
            return -6.0
        return -4.3 if tail == "iscal" else -1.7

    if split and tail in ("uc", "uf", "uck"):
        return 2.5
    if split and tail == "ime":
        return 3.0
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    previous = ""
    if carry is not None and carry[0] == document:
        previous = carry[1]
    return (document, token), response(previous, token)

"""Approximate numeric-formatting and quantity-modifier signals.

Digits directly after colons are negative, especially in numeric fields.
Zeros in single-integer-digit decimals are positive after the first fractional
place, with boosts below one and in leading fractional zero runs. Later
integer zeros are negative, more strongly with recent Han text. Measurement
suffixes, adjective + 'enough', and distance + 'away' add related cues.

This is a partial explanation: other words receive zero, not token-specific
learned offsets. Only 80 characters of history are retained; documents reset it.
"""
import re
import regex
import wordnet
from functools import lru_cache

READS = ()
NUMBER = re.compile(r"[0-9]+(?:\.[0-9]*)?$|\.[0-9]+$")
WORD = re.compile(r"([A-Za-z]+)$")
HAN = regex.compile(r"\p{Script=Han}")
METRIC_UNITS = {
    "m", "mm", "cm", "km", "nm", "g", "mg", "kg", "ml", "L", "V",
}
DISTANCE_WORDS = {
    "far", "farther", "further", "mile", "miles", "yard", "yards",
    "meter", "meters", "metre", "metres", "cm", "km", "units",
}


@lru_cache(maxsize=512)
def adjective(word):
    return "adjective" in wordnet.parts_of_speech(word.lower())


def zero_value(number, chinese):
    if "." in number:
        integer, fraction = number.rsplit(".", 1)
        n = len(fraction)
        if len(integer) <= 1:
            if n == 0:
                return 0.08
            value = 0.55 + 0.3 * (integer == "0")
            if not fraction.strip("0"):
                value += 0.4
            return max(0.0, value - 0.16 * max(0, n - 2))
        if n == 0:
            return -0.15
        if n == 1:
            return 0.1
        return 0.5 if n == 2 else max(-0.05, 0.4 - 0.15 * (n - 2))
    n = len(number)
    if chinese and n >= 2:
        return -0.55
    if n < 3:
        return -0.02
    if number.endswith("0"):
        return -0.25 if n == 3 else -0.4
    return -0.08 if n == 3 else -0.15


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is not None and carry[0] == doc:
        _, history, previous = carry
    else:
        history, previous = "", ""
    token = prefix.token_strings[-1]
    bare = token.strip()
    value = 0.0
    if len(token) == 1 and token in "0123456789":
        if history.endswith((":", "：")):
            before = history[:-1]
            numeric = (bool(before) and before[-1].isascii()
                       and before[-1].isdigit())
            if numeric:
                # Minute/second tens digits can only be 0 through 5.
                value = -1.45 if token < "6" else -0.85
            else:
                value = -0.3
            if previous not in (":", "："):
                value *= 0.3
        elif token == "0":
            match = NUMBER.search(history)
            if match:
                chinese = bool(HAN.search(history[-24:]))
                value = zero_value(match.group(), chinese)
    elif bare in METRIC_UNITS or bare in {"s", "%", "％", "°", "元"}:
        match = NUMBER.search(history.rstrip(" "))
        if match:
            number = match.group()
            if bare in {"%", "％"}:
                value = -0.3 if number.endswith("0") else -0.05
            elif bare in {"°", "元"}:
                value = -0.25 if bare == "°" else -0.4
            elif bare == "s":
                value = 0.4 if "." in number and number.endswith("0") else 0.0
            elif token.startswith(" "):
                value = 0.4 if "." in number else 0.0
            else:
                value = -0.45
    elif bare in {"enough", "away"}:
        match = WORD.search(history)
        word = match.group(1).lower() if match else ""
        if bare == "enough" and word and adjective(word):
            value = -1.3
        elif bare == "away" and word in DISTANCE_WORDS:
            value = -0.8 if word == "further" else -0.4
    return (doc, (history + token)[-80:], token), value

"""Recognize quantity bounds and exactness from their surface wording.

The strongest negative responses complete 'at least', 'at most', 'more
than', 'up to', and 'a total of'. Nearby negation, prepositions, and loose
corrections such as 'or at least' adjust their strength. Smaller rules
recognize temporal/adverbial expressions and a few translated bounds.
This approximates wording, not the number's meaning. Unmatched tokens get
zero. A 160-character tail supplies context and resets between documents.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail = ''
    else:
        tail = carry[1]
    token = prefix.token_strings[-1]
    boundary = (not tail or token[:1].isspace()
                or not (tail[-1].isalnum() or tail[-1] == '_'))
    word = token.strip().lower() if boundary else ''
    words = re.findall(r"[\w']+", tail.lower())
    prev = words[-1] if words else ''
    before = words[-2] if len(words) > 1 else ''
    value = 0.0
    joined = (tail + token).lower()

    if word == 'least':
        if prev == 'at':
            value = -7.2
            if before == 'or':
                value = -4.9
            elif before in {'of', 'for', 'with', 'by', 'in', 'to'}:
                value = -8.8
            elif before in {'is', 'be', 'the'}:
                value = -6.5
        elif prev == 'not':
            value = 3.2
        else:
            value = 0.6
    elif word == 'most' and prev == 'at':
        value = -5.9
    elif word == 'than':
        if prev == 'more':
            value = -2.6
            if before in {'no', 'not'}:
                value = -4.6
            elif before in {'has', 'have', 'had', 'containing'}:
                value = -4.2
            elif before in {'of', 'with'}:
                value = -3.6
            elif before in {'much', 'far', 'little', 'nothing', 'anything'}:
                value = -1.3
        elif prev == 'less':
            value = -1.3
        elif prev == 'fewer':
            value = -3.7
        elif prev in {'greater', 'higher', 'smaller', 'lower', 'faster', 'bigger'}:
            value = -0.55
        elif prev in {'rather', 'better', 'other'}:
            value = -0.2
        elif prev in {'longer', 'later'}:
            value = -2.3
        else:
            value = -0.8 if prev.endswith('er') else -0.1
    elif word == 'to':
        if prev == 'up':
            value = -1.8
            if before in {'of', 'for'}:
                value = -4.4
            elif before in {'be', 'go'}:
                value = -3.5
        elif prev == 'limited':
            value = -1.2
    elif word == 'of':
        if prev == 'total':
            value = -6.3 if before == 'a' else -2.7
        elif prev in {'maximum', 'minimum', 'max', 'average', 'multiples'}:
            value = -2.0
        elif prev == 'multiple':
            value = -1.25
    elif word == 'exactly':
        value = -2.3
        if prev in {'has', 'have', 'had', 'into', 'of', 'to', 'be', 'with'}:
            value = -3.8
        elif prev in {'not', 'know'}:
            value = -1.0
    elif word == 'course' and prev == 'of':
        value = -2.2
    elif word in {'year', 'week', 'month', 'season'}:
        if prev in {'this', 'last', 'next'}:
            value = -1.1
    elif word == 'more' and prev == 'or':
        value = -0.9
    elif word == 'less' and prev == 'or':
        value = -0.6
    elif word == 'as' and prev in {'much', 'long', 'far', 'soon'}:
        value = -0.8
    elif word == 'exceed':
        value = -2.0
    elif word == 'either':
        value = -0.48
    elif word == 'example' and prev == 'for':
        value = -0.47
    elif word == 'principle' and prev == 'in':
        value = -1.3
    elif word == 'average' and prev == 'on':
        value = -2.0
    elif word == 'much' and prev == 'pretty':
        value = -2.0
    elif word == 'but' and prev == 'all':
        value = -2.0

    # A few other languages' explicit quantity bounds.
    if word == 'menos' and prev == 'al':
        value = -7.9
    elif word == 'als' and prev == 'mehr':
        value = -2.3
    elif word == 'de' and prev in {'más', 'mais'}:
        value = -2.3
    elif word == 'менее' and prev == 'не':
        value = -3.4
    elif token.strip() in {'至少', '不少于', '超过'}:
        value = {'至少': -4.3, '不少于': -2.9, '超过': -1.45}[token.strip()]
    elif not boundary and word == '':
        if re.search(r'\bexactly$', joined):
            value = -5.4
        elif re.search(r'\bmindestens$', joined):
            value = -10.2
        elif re.search(r'\balmeno$', joined):
            value = -8.5
    elif word == 'mindestens':
        value = -10.2
    elif word == 'almeno':
        value = -8.5

    return (doc, (tail + token)[-160:]), value

"""Approximate an e-ending spelling feature, not a pronunciation model.

French-looking -ette/-elle endings, especially when completed across a
boundary between tokens, are positive. -ene/-enne and some other final-e
spellings are weaker positives. Short consonant+e fragments often have
negative values, depending on the consonant they join. Greek epsilon and
Cyrillic e have separate consonant-join rules. Unmatched tokens get zero.
Individual words and names can depart substantially from these patterns.
"""
import re
import codecs
import unicodedata
from functools import lru_cache

READS = ()

@lru_cache(maxsize=8192)
def latin(s):
    return ''.join(c for c in unicodedata.normalize('NFD', s.lower())
                   if not unicodedata.combining(c))


def activation(t, prior):
    s = t.strip()
    cont = bool(t[:1].isalpha() and prior)
    if s in {'ε', 'έ', 'Ε', 'Έ'}:
        if cont and 'GREEK' in unicodedata.name(prior[-1], ''):
            last = prior[-1].lower()
            if last in 'σςνθζχφ':
                return -1.37
            if last in 'μτδ':
                return -0.12
            return -0.64
        return 0.0
    if s in {'е', 'Е'} and cont and prior[-1].lower() in 'жшхщцч':
        return -0.49
    if s == '€' and prior.endswith('a'):
        return -1.5
    lo, p = latin(s), latin(prior)
    if not (lo.isascii() and lo.isalpha()):
        return 0.0
    if lo in {'rhe', 'rhes'}:
        return -1.13
    if not cont:
        return 0.0
    last = p[-1:]
    # Reconstruct endings whose first letters were in the previous token.
    word = p + lo
    if lo in {'le', 'les', 'lle', 'lles'} and re.search(r'elles?\Z', word):
        return 2.01
    if lo in {'te', 'tes', 'tte', 'ttes'} and re.search(r'ettes?\Z', word):
        return 2.65
    if re.search(r'lenes?\Z', word) and lo.endswith(('ene', 'enes', 'ne', 'nes')):
        return 1.98
    if re.search(r'arenes?\Z', word) and lo.endswith(('ene', 'enes', 'ne', 'nes')):
        return 1.67
    # Endings contained within the current fragment.
    if re.search(r'ettes?\Z', lo):
        if lo == 'ette' and last in 'mn':
