        if onset == 'k' and not plural:
            return 0.0 if last in 'aeiouy' else -1.02
        if onset in {'p', 'v'} and last in 'lr':
            return -1.7
        if onset == 'n' and last in 'lr':
            return -0.91
        if last in 'lr' and onset not in {'t', 'l'}:
            return -0.22
        if onset in {'ch', 'qu', 'z'} and last not in 'aeiouy':
            return -0.42
