    match = re.search(r'[^\W\d_]+\Z', prior + text)
    tail = match.group()[-60:] if match else ''
    return (doc, tail, data[consumed:]), prediction

programs.haiku:
"""Temporal-reference detector.

The component reads the calendar and the clock of a text. Its activation is large on
the word that places something in time:
  - month names (January, Aug, ...; capitalised May only), seasons, days of the week;
  - time-span nouns (year, decade, century, week, day, time, ...) and their
    translations (年, 月, Jahr, años);
  - temporal adverbs and adjectives (now, then, ago, since, before, next, past, ...), weaker;
  - the 'th' of an ordinal after a digit ('18th'), and the 's' of '1970s';
  - the last digit of a four-digit year ('199[9]', '202[2]');
  - the spacer or dot right after an abbreviated month ('Sep 17', 'Aug.').
A time word right after a relative marker ('the past year', 'the following day',
'each time') fires more strongly. Everything else is predicted as 0.
"""

READS = ()

MONTHS = {
    "january", "february", "march", "april", "june", "july", "august",
    "september", "october", "november", "december",
    "jan", "feb", "mar", "apr", "jun", "jul", "aug", "sep", "sept", "oct", "nov", "dec",
}
ABBREVIATED = {m for m in MONTHS if len(m) <= 4}
SEASONS = {"spring", "summer", "fall", "autumn", "winter", "season", "seasons"}
DAYS = {"monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday", "weekend"}
SPANS = {
    "year", "years", "decade", "decades", "century", "centuries", "month", "months",
    "week", "weeks", "day", "days", "time", "times", "era", "generation", "date",
    "period", "semester", "hour", "hours", "night", "morning", "afternoon",
    "年", "月", "日", "週", "季", "年来", "今年", "jahr", "jahren", "ans", "años", "anos",
}
ADVERBS = {
    "ago", "now", "then", "soon", "later", "before", "after", "until", "since", "while",
    "earlier", "previously", "recently", "recent", "present", "past", "future", "next",
    "previous", "following", "early", "late", "once", "today", "currently", "latest",
    "when", "whenever", "first", "second", "third", "fourth", "fifth",
}
RELATIVE = {"past", "following", "last", "next", "each", "every", "this", "that", "same"}


def is_digit(text):
    return len(text) == 1 and text.isdigit()


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1].strip()
    word = raw.lower()
    before = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if is_digit(raw) and len(prefix) >= 4:
        last4 = [s.strip() for s in prefix.token_strings[-4:]]
        if all(is_digit(s) for s in last4) and last4[0] + last4[1] in ("19", "20"):
            return carry, 0.6
    if word == "may" and raw[:1].isupper():
        value = 1.5
    elif word in MONTHS or word in SEASONS:
        value = 1.5
    elif word in DAYS or word in SPANS:
        value = 1.0
    elif word in ADVERBS:
        value = 0.4
    elif word in ("th", "nd", "rd", "st") and before.isdigit():
        value = 2.0
    elif word == "s" and before.isdigit():
        value = 0.7
    elif before in ABBREVIATED and word == ".":
        return carry, 2.0
    elif before in ABBREVIATED and word == "":
        return carry, 1.0
    else:
        return carry, 0.0
    if before in RELATIVE:
        value += 0.6
    return carry, value

"""Definite-article detector (layers.1.mlp.down_proj, component 5448).

The component fires on the definite article "the" (also "The", "THE") and on its
equivalents in German, French, Spanish, Portuguese and Italian ("die", "der", "das",
"la", "les", "los", ...). It is silent on indefinite and other determiners ("a", "an",
"this", "that", "his") and on pronouns.

How strongly it fires depends on the word just before the article:
  - after a preposition or a verb that takes an object ("in the", "on the", "to the",
    "use the"): strongest, about 1.4;
  - after "of" or any other word: about 1.0;
  - after a copula or a conjunction ("is the", "was the", "and the", "all the"): weak,
    about 0.5.
Foreign articles are scaled by 0.8. Everything else predicts 0. The levels are rough
group means read off the training data; the position in the document, and the rest of
the context, barely matter.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

THE = {" the", " The", " THE"}
FOREIGN_ARTICLES = {" die", " der", " das", " den", " dem", " des", " du", " del", " la", " le", " les", " el", " los", " las", " l"}
PREPOSITIONS_AND_OBJECT_VERBS = {
    " in", " on", " about", " during", " into", " from", " for", " with", " by", " to", " at",
    " under", " over", " between", " within", " through", " that", " using", " In", " when",
    " if", " where", " as", " than", " containing", " including", " use", " see", " understand",
    " verify", " reduce", " determine", " include",
}
COPULAS_AND_CONJUNCTIONS = {
    " is", " was", " are", " be", " were", " been", " and", " or", " all", " have", " has",
    " had", " not",
}


def step(carry, prefix, upstream: Mapping):
    token = prefix.token_strings[-1]
    if token not in THE and token not in FOREIGN_ARTICLES:
        return carry, 0.0
    # The word before the article, within the same document (empty at a document start).
    before = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if len(prefix) > 1 and prefix.document_ids[-2] != prefix.document_ids[-1]:
        before = ""
    if before in PREPOSITIONS_AND_OBJECT_VERBS:
        value = 1.4
    elif before in COPULAS_AND_CONJUNCTIONS:
        value = 0.5
    else:
        value = 1.0
    if token in FOREIGN_ARTICLES:
        value *= 0.8
    return carry, value

programs.sol:
"""Approximate a context-sensitive NO spelling and number-reference feature.

Usually negative on no/No, especially number labels and code/error names.
Recognizes short o/O (or zero) fragments after n/N, plus N° and Nº.
Italian context makes 'con' and '-ino' fragments positive; Portuguese
'no' is predicted near zero or weakly positive. Other tokens get zero.
This is not general reasoning about negation. The short context window
resets at document boundaries.
"""
import re
import unicodedata

READS = ()
ITALIAN = {'il', 'gli', 'della', 'delle', 'degli', 'dei', 'che', 'non',
           'di', 'dalla', 'alla', 'nel', 'nella', 'sono', 'dello', 'anche'}
PORTUGUESE = {'não', 'uma', 'com', 'dos', 'das', 'para', 'os', 'as',
              'do', 'da', 'é', 'em', 'pelo', 'pela', 'são', 'mais'}


def predict(old, s):
    if s in {'º', '°'} and old.rstrip().endswith(('N', 'N.')):
        return -2.8
    low = s.strip().lower()
    folded = unicodedata.normalize('NFD', s)
    cross = (len(s) <= 3 and folded.startswith(('o', 'O', '0'))
             and old.endswith(('n', 'N', 'n_', 'N_')))
    no = re.fullmatch(r'[\W_]*no', s, re.I) is not None
    plural = low in {'nos', 'no.'}
    if not (no or plural or cross or low in {'con', 'ino', 'eno', 'errno'}):
        return 0.0
    # Read escaped line breaks as separators for word and reference cues.
    text = old.replace('\\n', '\n').replace('\\t', '\t')
    words = re.findall(r'[^\W\d_]+', text[-400:].lower())
    italian = (sum(w in ITALIAN for w in words) >= 3
               and len(set(words) & ITALIAN) >= 2)
    portuguese = (sum(w in PORTUGUESE for w in words) >= 3
                  and any(w in {'não', 'uma', 'com', 'dos', 'das', 'pelo',
                                'pela', 'são', 'mais'} for w in words))
    if cross:
        if re.search(r'(?:errno\.EN|\bEN)\Z', old):
            return -11.0 if s == 'O' else -3.5
        if s.startswith('0'):
            return -1.8 if re.search(r'(\b[nN]_?|[A-Z]N)\Z', old) else -0.15
        if italian and old.lower().endswith('con'):
            return 4.5
        if italian:
            return 0.3
        return -1.5 if len(s) == 1 else -0.35
    if low == 'con':
        return 1.4 if italian else 0.0
    if low == 'ino':
        return 2.5 if italian else 0.7
    if low == 'eno':
        if s == 'ENO':
            return -6.5  # POSIX error names: ENOENT, ENOTDIR, ...
        return -8.0 if old.lower().endswith(('phon', '_')) else -2.3
    if low == 'errno':
        return -4.0
    if low == 'nos' and not s.strip().startswith('N'):
        return 0.3 if portuguese else -0.35
    if re.match(r'[\W_]*N', s):
        if old.endswith('Err'):
            return -5.0
        if re.search(r'\b(Pat|Ser|Sr)\.?\s*$', text):
            return -5.4
        if re.search(r'\b(File|Page|Application|Docket|Serial|Patent|Case|Bar|Roll|'
                     r'Registration|SEQ ID)'
                     r'\.?\s*$', text, re.I):
            return -4.2
        if re.search(r'\b(Contract|License|Lease|Solicitation|Series|Calendar)\s*$',
                     text, re.I):
            return -2.7
        if re.search(r'Patent.*(Open|Publication)\s*$', text, re.I):
            return -4.2
        if re.search(r'(page|phone|seq|reference)$', old, re.I):
            return -4.8
        word_start = (s[0].isspace() or not text or text[-1].isspace())
        if portuguese and word_start:
            return 0.2
        if italian and word_start:
            return 0.8
        if s.strip() == 'NO':
            return -2.3
        if s[0] in '._-/(':
            return -2.7
        return -1.4 if s.startswith(' ') else -1.9
    if s == ' no':
        if re.search(r'\b(is|are|was|were|has|have|had|with)\s*$', old):
            return -0.2
        if re.search(r'\b(pub|int|var|let|const|eslint|pylint|'
                     r'disable|disable-line)\s*$', text):
            return -3.4
        return 0.4 if portuguese else -0.6
    if old.lower().endswith('err'):
        return -8.8
    if old.endswith('--'):
        return -4.5
    if s[0] in '/_-':
        if s[0] == '/':
            return -5.0 if old.endswith('rules') else -3.7
        if s[0] == '_':
            return -3.0
        if old.endswith('signal-to'):
            return 1.5
        return -4.5 if any(w in old for w in ('pylint', 'eslint', 'rules')) else -1.8
    if s[0] in '.(':
        return -2.5
    if s == 'no' and old and old[-1].isalpha():
        return 1.3 if italian else -0.4
    if old.endswith(('`', '"', "'", '(')):
        return -2.5
    return -2.7


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = '' if carry is None or carry[0] != doc else carry[1]
    s = prefix.token_strings[-1]
    return (doc, (old+s)[-500:]), predict(old, s)

"""Approximate a response to delimiters introducing structured items.

Opening dictionary-key quotes and backticks in densely marked-up code are
positive. A ### heading after a long, unfinished paragraph is negative;
a paragraph break after a repeated title gets a similar negative response.
Small additional rules cover literal newline escapes and two document-start
word classes: C-style declarations and capitalized words with a verb reading.
Everything else is zero.
This deliberately omits the component's many small lexical effects and its
irregular responses to individual words at document starts.
"""
import re
import wordnet

READS = ()
C_STYLE_DECLARATIONS = frozenset(
    'int char short long float double void bool string const var let '
    'function class module struct enum using'.split()
)
AUXILIARIES = frozenset(
    'be am is are was were being been have has had do does did will would '
    'shall should can could may might must'.split()
)
FIELD = re.compile(r"[\"'][^\"'\n]{1,80}[\"']\s*(?::|=>)")


def unfinished(text):
    paragraph = text.rstrip().rsplit('\n\n', 1)[-1]
    return (len(paragraph) > 100 and '\n' not in paragraph
            and paragraph[-1] not in '.!?:;`。！？')


def repeated_title(text):
    parts = text.rsplit('\n\n', 2)
    if len(parts) < 2 or not parts[-2].startswith('### '):
        return False
    title = re.findall(r'[A-Za-z]+', parts[-2][4:].lower())
    body = re.findall(r'[A-Za-z]+', parts[-1].lower())
    return bool(title and body and title[0] == body[0])


def fragment_key(text):
    """Infer a key in a mapping whose opening brace may precede this row."""
    if not FIELD.search(text[-512:]):
        return False
    indentation = text.rsplit('\n', 1)[-1].strip() in ('', '+', '-', 'E')
    if not (text.rstrip().endswith(',') or indentation):
        return False
    curly = text.rfind('{')
    value_list = any(text.rfind(a) > max(text.rfind(b), curly)
                     for a, b in (('[', ']'), ('(', ')')))
    # PHP also writes associative arrays with => inside square brackets.
    return not value_list or ('=>' in text[-512:] and indentation)


def response(token, recent, stack, quote, last):
    if not recent:
        if token in C_STYLE_DECLARATIONS:
            return 2.2
        if token == '##':
            return 0.9
        if (token.isalpha() and token[:1].isupper() and token[1:].islower()
                and token.lower() not in AUXILIARIES
                and 'verb' in wordnet.parts_of_speech(token.lower())):
            return -0.33
    if token == '###':
        if not recent:
            return 1.6
        return -0.9 if unfinished(recent) else 0.0
    if token.endswith('\n\n'):
        text = recent + token.rstrip('\n')
        if unfinished(text) and repeated_title(text):
            return -0.6

    # Treat quotes opening keys differently from quotes opening values.
    if token in ('\\"', ' \\"'):
        plain = recent.replace('\\"', '"').replace('\\n', '\n')
        if plain.rstrip().endswith('{') or fragment_key(plain):
            return 0.8
    if token.lstrip() in ('","', ',"', "','", ",'"):
        if stack and stack[-1] == '{':
            return 0.7
    if token in (' "', " '", '"', "'"):
        if not quote and stack and stack[-1] == '{' and last in '{,':
            if token.endswith("'"):
                return 1.1
            if last == '{' or not recent.rsplit('\n', 1)[-1].strip():
                return 1.0
            return 1.4
        return 1.0 if fragment_key(recent) else 0.0

    # Copied code sometimes wraps almost every word and space in backticks.
    if token.strip() == '`':
        window = recent[-256:]
        if '\xa0' in window and window.count('`') >= 4:
            previous = recent.rstrip(' \t\r\n')
            if previous.endswith('{'):
                return 2.0
            if previous.endswith(';'):
                return 1.7
            if recent.endswith(' `'):
                return 0.8
            if recent.endswith('`') or not recent.rsplit('\n', 1)[-1].strip():
                return 0.25
            return 1.3
    if token == '\\n':
        return 0.13
    if token == 'n' and recent.endswith('\\'):
        return -0.12
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', [], '', False, '')
    _, recent, stack, quote, escaped, last = carry
    token = prefix.token_strings[-1]
    value = response(token, recent, stack, quote, last)

    # Keep only bracket/string syntax, not the contents of the whole document.
    stack = stack.copy()
    for char in token:
        if quote:
            if escaped:
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == quote:
                quote = ''
                last = char
        elif char in '{[(':
            stack.append(char)
            last = char
        elif char in '}])':
            if stack:
                stack.pop()
            last = char
        elif stack and char in "\"'":
            quote = char
        elif not char.isspace():
            last = char
    return (doc, (recent + token)[-1536:], stack, quote, escaped, last), value

"""Detect 'in/on'-like locative prepositions and word-initial fragments.

The signal is weaker for grammatical complements ('interested in', 'based
on') than for locations and dates. Ambiguous foreign spellings are resolved
by the recent text's word frequencies. Inside-word fragments are usually
suppressed. A separate negative offset marks document starts, estimated
from whether the token is a word, number, whitespace or other symbol.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency
import wordnet

READS = ()

LOCATIVE = {
    'in': 1.24, 'on': 0.90, 'upon': 0.96,
    'в': 1.80, 'на': 0.98, 'во': 0.60,
    'auf': 0.61, 'sur': 0.58, 'på': 1.25,
    'na': 1.10, 'في': 0.87, 'على': 0.80,
    'nel': 0.31, 'nelle': 0.41, 'within': 0.20,
}
LANGUAGES = {
    'en': ('es', 'fr', 'nl', 'en', 'de', 'pt', 'tr'),
    'em': ('pt', 'en', 'it', 'vi'),
    'im': ('de', 'en', 'pt'),
    'w': ('pl', 'en', 'de'), 'v': ('cs', 'en'),
    'у': ('uk', 'ru'), 'no': ('pt', 'en', 'es'),
}
FOREIGN_LOCATIVE = {
    ('en', 'es'): 2.70, ('en', 'fr'): 0.93,
    ('em', 'pt'): 2.85, ('im', 'de'): 0.90,
    ('w', 'pl'): 2.60, ('v', 'cs'): 1.40,
    ('у', 'uk'): 2.10, ('no', 'pt'): 0.90,
}
# English heads that govern a non-locative prepositional complement.
GOVERN_IN = set('''increase decrease reduction change difference variation
    improvement interest involve engage include participate specialize
    result'''.split())
GOVERN_ON = set('''base depend dependent dependence rely reliance focus
    effect impact influence emphasis concentrate'''.split())
PRESENTED_IN = set('''show mention describe specify depict illustrate
    disclose explain'''.split())
# These heads usually introduce the location or date of an event.
LOCATION_IN = set('''born live reside work available publish appear
    build make election birth death'''.split())


@lru_cache(maxsize=30000)
def frequency(word, language):
    return zipf_frequency(word, language)


def language_of(text, languages):
    words = re.findall(r'[^\W\d_]+', text.lower())[-25:]
    scores = {lang: sum(frequency(w, lang) for w in words if len(w) > 1)
              for lang in languages}
    best = max(scores, key=scores.get)
    return best if scores[best] >= 6.0 else ''


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    state = (doc, (text + token)[-600:])
    if not text:
        if token.startswith(' ') and word in ('in', 'on'):
            value = 0.0
        elif token.strip().isalpha():
            value = -0.60
        elif token.strip().isdigit():
            value = -0.10
        else:
            value = -0.22 if not token.strip() else -0.30
        return state, value
    if not token:
        return state, 0.0
    boundary = not token[0].isalpha() or not text[-1].isalpha()
    if not boundary:
        # Camel-case In/On still weakly resemble the prepositions.
        return state, {'In': 0.35, 'On': 0.58}.get(token, 0.0)
    value = LOCATIVE.get(word, 0.0)
    if word in LANGUAGES:
        lang = language_of(text, LANGUAGES[word])
        value = FOREIGN_LOCATIVE.get((word, lang), 0.0)
    if word in ('in', 'on'):
        previous = re.search(r'([^\W\d_]+)$', text)
        head = previous[0].lower() if previous else ''
        bases = wordnet.base_forms(head) if head else ()
        head = bases[0] if bases else head
        if word == 'in':
            # Mathematical membership and for-loop variables are not places.
            if (text.endswith(('\\', '\\<'))
                    or (len(head) == 1 and head != 'a'
                        and previous[0].islower())
                    or re.search(r'\bfor\s+\w+(?:\s*,\s*\w+)*$', text)):
                return state, -0.15
            if head in GOVERN_IN:
                value = 0.43
            elif head in PRESENTED_IN:
                value = 0.78
            elif head in LOCATION_IN:
                value = 1.72
        elif head in GOVERN_ON or head == 'so':
            value = 0.10
        if token.strip().isupper():
            value *= 0.63
        elif word == 'on' and token.strip().istitle():
            value *= 0.70
    return state, float(value)

"""A partial approximation using stock phrases and document-opening syntax.

Acknowledgements, their punctuation, and familiar qualifications have negative
responses; help requests and statements of a task have positive responses.
There are also explicit Chinese courtesy/label phrases and Russian 'in order
to'. Separate rules recognize initial source-file keywords and 'Title:'.
Unrecognized tokens give zero, rather than modeling the small background
activations. The only state is 160 characters of document-local history.
"""
import re

READS = ()
ACKNOWLEDGEMENTS = {'yes', 'sure', 'certainly', 'absolutely'}
GREETINGS = {'hello', 'hi', '你好', '您好', '欢迎您', '好的'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    text = (before + token)[-160:]
    lower = text.lower()
    previous = re.search(r'(\w+)$', before)
    previous_raw = previous.group(1) if previous else ''
    previous = previous_raw.lower()
    opening = bool(re.search(r'(?:^|[.!?]\s+|\n\s*)$', before))
    assistant = bool(re.search(
        r'assistant\n(?:<think>\s*</think>\s*)?$', before))
