"""A sparse lexical approximation, not a single semantic detector.

Positive peaks mark web-view labels and React imports. Document starts
have much larger lexical offsets: integer/Boolean type names are positive,
whereas import directives, finite verbs and several format controls are
negative. Dotted leaders also give a negative response. Small rules for
additive adverbs, comparisons and Boolean literals cover some background
variation. These rules deliberately leave most lexical variation unmodeled.
"""
import re

READS = ()
FINITE_VERBS = set('am is are was were be been being can could will would '
                   'shall should may might must'.split())
PRONOUNS = set('i we he she it they you'.split())
PREPOSITIONS = set('of to from in at with for on by as'.split())
CONJUNCTIONS = set('and or but if'.split())
RELATIVES = set('which that who whom whose where when what why how'.split())


def initial_value(token):
    word = token.strip().lower()
    if token in ('int', 'bool'):
        return 1.89
    if token == 'string':
        return -0.94
    if token in ('User', 'Users', 'user'):
        return 0.63 if token == 'user' else 1.25
    if token in ('import', 'using', 'export'):
        return -0.95
    if token == 'package':
        return -0.38
    if token == '<|im_start|>':
        return -0.21
    if token == '<|endoftext|>':
        return 0.84
    if token == '\x00':
        return -2.01
    if token == '\t':
        return -0.96
    if token == '\xa0':
        return -1.08
    if token.isascii() and token.isdigit():
        return 0.12
    if word in FINITE_VERBS:
        return -0.47
    if word in PRONOUNS:
        return -0.24
    if word in ('a', 'an'):
        return 0.38
    if word in PREPOSITIONS:
        return -0.11
    if word in CONJUNCTIONS:
        return -0.30
    if word in RELATIVES:
        return -0.36
    if token.startswith('-') and len(token) > 4 and token[1:].islower():
        return 0.55
    return -0.04


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    history = '' if first else carry[1]
    token = prefix.token_strings[-1]
    text = history + token
    word = token.strip().lower()
    value = initial_value(token) if first else 0.0024
    if not first and token.startswith(' '):
        if word in ('also', 'too', 'always'):
            value = 0.064
        elif word in ('now', 'then', 'next', 'while'):
            value = 0.030
        elif word in ('true', 'false'):
            value = -0.064
        elif word == 'than':
            value = -0.042
    if len(token) >= 2 and set(token) == {'·'}:
        value = -1.57
    elif token.strip() == 'React' and re.search(r'\bimport\s+React$', text):
        value = 1.03 if history == 'import' else 0.84
    elif token.strip() == 'Document' and text.endswith('View Full Document'):
        value = 1.05 if 'intentionally blurred' in history else 0.79
    elif token.strip() == 'Full' and text.endswith('View Full'):
        value = 0.35
    elif word == 'more' and re.search(r'\bView [Mm]ore$', text):
        value = 0.83
    elif token == ' protected' and text.endswith('[email protected'):
        value = 0.61
    elif token == 'Mass' and text.endswith('Explore BrainMass'):
        value = 0.66
    return (doc, text[-256:]), value

programs.haiku:
"""Writes into an object slot in code (layers.1.mlp.down_proj:5456).

Strongly negative on the operator of an assignment that writes into an existing
field, index or pointer on an indented line (`self.time = `, `result[key] = `,
`node->next = `). Also negative, less so, on comparisons and on plain assignments in
indented code. Near zero elsewhere, including prose and maths.
"""
import re

READS = ()

ASSIGN = {" =", "=", " :=", " <-", " +=", " -=", " *=", " /="}
COMPARE = {" ==", "==", " !=", "!=", " ===", " >=", " <=", " >", " <", " &&", " ??"}
STORE_TARGET = re.compile(r"(\]|\.\w+|->\w+)$")
DOTTED = re.compile(r"\w\.\w")


def step(carry, prefix, upstream):
    line = carry or ""
    docs = prefix.document_ids
    if len(docs) > 1 and docs[-1] != docs[-2]:
        line = ""
    token = prefix.token_strings[-1]
    value = 0.0
    if token in ASSIGN or token in COMPARE:
        before = line.rstrip()
        indented = line[:1] in (" ", "\t")
        store = STORE_TARGET.search(before) is not None
        if token in ASSIGN:
            if store:
                value = -4.9 if indented else -1.5
            elif indented:
                value = -0.4
        else:
            if store:
                value = -2.4 if indented else -1.0
            elif indented:
                value = -0.85 if DOTTED.search(before) else -0.35
    line = (line + token).split("\n")[-1]
    return line, value

