"""A beginning-of-context response, mostly silent after a different token arrives.

At the beginning, estimate the response from token shape, literal escapes and
small grammatical families. Decimal digits have a rising magnitude response.
This deliberately omits the component's much finer word-by-word variation.
"""
import unicodedata

READS = ()

# Additive adjustments for familiar closed grammatical classes.
GRAMMAR = (
    (frozenset('the'.split()), -2.42),                    # definite article
    (frozenset('for'.split()), -2.92),                    # purpose
    (frozenset('as than like'.split()), -2.84),           # comparison
    (frozenset('be am is are was were been being'.split()), -1.67),
    (frozenset('by'.split()), 3.49),                      # agency
    (frozenset('and or but yet so'.split()), 1.67),       # conjunction
    (frozenset('i me my mine myself'.split()), -1.92),
    (frozenset('have has had having'.split()), -2.89),
    (frozenset('it its itself'.split()), 2.27),
)
DECLARATIONS = frozenset('package import using class interface struct enum '
                         'typedef namespace def function'.split())
QUESTIONS = frozenset('who whom whose what when where why how which'.split())
PLURAL_PRONOUNS = frozenset('they them their theirs themselves'.split())


def initial_response(s):
    text = s.strip()
    low = text.lower()
    leading = bool(s and s[0].isspace())
    capital = bool(text and text[0].isupper())

    # Literal serialized controls are unusually strong initial-token signals.
    if text == r'\t':
        return 41.16
    if text == r'\n':
        return 17.08
    if text == '\0':
        return 14.25

    value = -0.035 + 0.80 * leading
    if len(text) == 1 and text.islower():
        value += 2.08
    if len(text) > 1 and text.isalpha():
        value += 0.46
    if s.isspace():
        value += 3.29 * min(len(s), 32) / 16
        if s == ' ':
            value -= 2.37
    if len(text) == 1 and text.isdecimal():
        value += -2.97 + 5.59 * unicodedata.decimal(text) / 9

    if '\\' in text and len(text) > 1:
        value += 8.72
    if '\\"' in text or "\\'" in text:
        value += 3.90
    if '&' in text:
        value += 5.21
    if text.startswith('#'):
        value -= 2.55
    if text.startswith('/*'):
        value -= 3.26
    for symbols, adjustment in (('.', -2.09), ('([{', -2.54), ('-–—', -1.76)):
        if text and all(ch in symbols for ch in text):
            value += adjustment
    if text.startswith('<|'):
        value -= 0.90

    if not leading and low in DECLARATIONS:
        value -= 4.43
    if capital and low in QUESTIONS:
        value -= 4.20
    if capital and low in PLURAL_PRONOUNS:
        value += 4.41
    for words, adjustment in GRAMMAR:
        if low in words:
            value += adjustment
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != document:
        value = initial_response(prefix.token_strings[-1])
        carry = (document, token, True, value)
    elif carry[2] and token != carry[1]:
        carry = (document, carry[1], False, carry[3])
    return carry, float(carry[3] if carry[2] else 0.0)

