    'i': 'I', 'you': 'you', 'we': 'we', 'he': 'he/she', 'she': 'he/she',
    'they': 'they', 'it': 'it', 'who': 'who',
    **dict.fromkeys(('there', 'this', 'that', 'these', 'those', 'which'), 'this'),
