    'you':    (0.0, -6.6, -0.4, -5.3, -5.9, -5.2),
    'we':     (0.0, -6.0, -0.4, -5.3, -5.7, -5.6),
    'he/she': (-3.9, -0.4, -3.9, -4.0, -4.8, -5.1),
    'they':   (0.0, -2.6, -0.4, -3.0, -2.4, -3.2),
    'it':     (-0.4, 0.0, -0.4, -0.5, -0.5, -0.6),
    'this':   (0.1, -0.1, 0.0, -0.2, 0.1, -0.6),
    'who':    (-3.2, -3.1, -3.2, -2.6, -3.8, -3.9),
    'human':  (-0.6, -0.8, -1.7, -1.0, -1.8, -2.1),
    'name':   (-0.2, -0.3, -1.0, -0.7, -0.8, -1.8),
    'other':  (0.0, -0.2, -0.3, -0.3, -0.6, -1.0),
