OTHER_BE_FORMS = {
    'être': -2.2, 'etre': -2.6, 'étant': -3.0, 'été': -1.5,
    'suis': -5.3, 'êtes': -5.7, 'est': -1.2, 'sont': -1.0, 'était': -2.5,
    'estar': -3.5, 'está': -3.5, 'están': -3.3, 'estava': -3.7,
    'estoy': -6.5, 'estamos': -6.0, 'estou': -5.5,
    'essere': -2.6, 'sono': -1.4, 'siamo': -6.0, 'siete': -5.0,
