"""Approximate Slavic subword-ending response, not a general letter-y detector.

Cyrillic ы endings, Ukrainian-context и, and West-Slavic consonant+y
fragments contribute negatively. Some front-vowel endings contribute positively. Recent distinctive
letters and relative word frequencies estimate the language; English words and
several conjunction tokens are discounted. Gains were fitted on training rows.
Small separate rules cover repeated middle dots and two document openings.
Remaining token-specific and contextual variation is not represented.
"""
import re
from functools import lru_cache

import regex
from wordfreq import zipf_frequency

READS = ()
SLAVIC_MARKS = frozenset('ěščřžůďťňľĺŕłńśźżęąć')
CONJUNCTIONS = frozenset(('czy', 'gdy', 'kdy', 'kiedy', 'aby', 'żeby'))
CYRILLIC_VOWELS = frozenset('аеёиоуыэюя')


@lru_cache(maxsize=65536)
def frequencies(word):
    return (max(zipf_frequency(word, lang) for lang in ('cs', 'sk', 'pl')),
            zipf_frequency(word, 'en'))


@lru_cache(maxsize=65536)
def slavic_word(word):
    if len(word) < 3 or len(word) > 40 or ord(word[0]) > 0x250:
        return 0.0
    if SLAVIC_MARKS.intersection(word):
        return 1.0
    slavic, english = frequencies(word)
    if slavic < 3:
        return 0.0
    return min(1.0, max(0.0, (slavic - english - .5) / 2))


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, '', 0.0, 0.0, 0, '', 0.0)
    _, word, language, ukrainian, position, head, marks = carry
    previous_word = word
    token = prefix.token_strings[-1]
    s = token.lower()
    bare = s.strip()

    marks = max(.99 * marks, float(bool(SLAVIC_MARKS.intersection(s))))
    ukrainian = max(.99 * ukrainian, float(bool(set('іїєґ').intersection(s))))
    # Update language evidence only when a word is completed.
    for part in re.findall(r'[^\W\d_]+|[\W\d_]+', s):
        if part.isalpha():
            word += part
        else:
            if word:
                language = .7 * language + .3 * slavic_word(word)
            word = ''
    lexical = max(min(1.0, 2 * language), slavic_word(word))
    value = 0.0

    if s.isalpha():
        n = len(s)
        scale = 1.0 / max(1, n - 1)
        if s.endswith('ы'):
            value -= 1.16 * scale
            value -= .16 * (n == 1)
            value += .28 * (n == 2 and s[0] in 'рлн')
            value += .23 * (n >= 3 and not CYRILLIC_VOWELS.intersection(s[:-1]))
        if s.endswith('и'):
            value -= 1.29 * ukrainian * scale
            value -= .40 * s.endswith(('ки', 'ги', 'хи'))
        if s.endswith('у'):
            value -= .12 * scale
        if s.endswith('і'):
            value += .17 * scale

    if bare and regex.fullmatch(r'\p{Latin}+', bare):
        slavic, english = frequencies(word)
        confidence = 1.0
        if english > 3:
            confidence -= min(1.0, max(0.0, (english - slavic) / 2))
        context = confidence * (.4 * lexical + .6 * marks)
        if bare in CONJUNCTIONS:
            context *= .1
