            gain += 1.73 * (initial and len(bare) > 3)
            value += context * gain
        if bare.endswith('e'):
            value += context * (.22 - .16 * initial + .19 * single)
        if bare.endswith('u'):
            value += context * (-.41 + .32 * initial)
        if bare.endswith(('ki', 'gi', 'hi')):
            value -= .94 * context
        if bare.endswith(('im', 'ím')):
            value += .91 * context
        if 'í' in bare or (not initial and len(bare) <= 2
                           and previous_word.endswith('í')):
            value += .28 * context
        if bare.endswith('í'):
            value -= .08 * lexical * confidence
        if bare.endswith('ý'):
            value -= .34

    if len(s) > 1 and set(s) == {'·'}:
        value -= .444 * len(s)
    if position < 4:
        head += token
        if head == 'Title:':
