LIMITERS = {
    'a', 'an', 'the', 'this', 'these', 'those', 'which',
    'my', 'your', 'his', 'her', 'its', 'our', 'their',
    'each', 'every', 'only', 'least', 'most', 'exactly',
}
PREPOSITIONS = {
    'to', 'with', 'by', 'for', 'into', 'about', 'within',
    'around', 'over', 'under', 'through', 'between', 'among',
    'before', 'after', 'without', 'upon', 'across', 'off', 'out', 'near',
}

AUXILIARIES = {
    'am', 'is', 'are', 'was', 'were', 'be', 'being', 'been',
    'have', 'has', 'had', 'having', 'do', 'does', 'did',
    'can', 'could', 'will', 'would', 'shall', 'should', 'may', 'might', 'must',
}


def one_after(previous, earlier=''):
    if previous == 'from':
        return 6.8
    if previous in {'of', 'in', 'on', 'during', 'along'}:
        return 4.6
    if previous == 'at':
        return 4.0
    if previous in PREPOSITIONS or previous in {'any', 'when', 'where'}:
        return 2.8
    if previous == 'no':
        return -0.1
    if previous in LIMITERS:
        return 0.22
    if previous in {'just', 'not', 'even'}:
        return 0.8
    if previous in {'that', 'some'}:
        return 1.7
    if previous in {'and', 'but', ',', ':', ';', '('}:
