    if previous == 'if':
        return 2.2
    if previous in AUXILIARIES:
        return 1.1
    if previous == 'number':
        return 0.1
    parts = wordnet.parts_of_speech(previous)
    if 'adjective' in parts:
        if 'verb' not in parts or 'adverb' in parts or earlier in LIMITERS:
