"""Approximate a code-formatting and delimiter response.

Strong positives mark tabs after line numbers, mixed space/tab indentation,
and indentation after an escaped (not actual) newline. Smaller rules mark
assignment and namespace separators, quotation endings, test declarations,
nonbreaking-space formatting, an HTML apostrophe escape, and chat spacing. Otherwise the prediction is zero.
The beginning-of-text marker also has an initial spike.
"""
import math
import re

READS = ()
ASSIGNMENTS = {' =', ' :=', ' <-'}
QUOTE_ENDINGS = {',"', ',”', ",''", '!"', '?"', '”,'}
TEST_CALLS = {'it', 'describe', 'test', 'suite'}


def formatting(token, previous, history):
    leading = re.match(r'[ \t]+', token)
    if not leading or not (token.isspace() or '\t' in leading[0]):
        return None
    blank = leading[0]
    spaces, tabs = blank.count(' '), blank.count('\t')
    if tabs and previous.endswith(' '):
        trailing = len(previous) - len(previous.rstrip(' '))
        return min(3.0, 1.8 + 0.2 * trailing)
    if ' \t' in blank:
        return min(2.5, 0.4 + 0.45 * spaces)
    if (spaces and '\t' in previous and previous[-1:].isspace()
            and '\n' not in previous):
        return min(2.1, 0.85 + 0.045 * spaces + 0.2 * tabs)
    if '\n' in token:
        return 0.0
    if tabs and previous[-1:].isdigit():
        return min(1.85, 0.60 + 0.05 * spaces + 0.40 * math.log2(tabs))
    if tabs:
        return 0.3 if spaces else -0.08
    if history.endswith('\\n'):
        base = 0.96 if previous == 'n' else 0.62
        return base - (0.35 if spaces == 1 else 0.0)
    if spaces > 1 and previous.rstrip().endswith(('//', '#')):
        return 0.5
    return -0.05 if spaces > 1 and previous.endswith('\n') else 0.0


