        return 1.0
    if token and set(token) == {'\xa0'}:
        return 0.3 if len(token) > 1 else 0.0

    # Only these separators and test-related words need identifier context.
    is_test = token.strip() in ('test', 'Test')
    if token not in ASSIGNMENTS | {'::', "('", '("', ' void'} and not is_test:
        return 0.0
    match = re.search(r'[\w$]+$', history)
    word = match[0] if match else ''
    if token in ASSIGNMENTS:
        if token == ' <-':
            return 0.8
        if not word or word.isdigit():
            return -0.08
