    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    start = carry is None or carry[0] != document
    previous, history = ('', '') if start else carry[1:]
    token = prefix.token_strings[-1]
    value = predict(token, previous, history, start)
    return (document, token, (history + token)[-300:]), value

