Large negatives mark hypothetical 'were', prospective 'were to',
conditional 'had', 'need not', and Russian conditional-particle tokens.
Smaller rules cover bare 'be', several 'but' constructions and imperative
phrases. Positive rules cover 'better/worse', 'something else', calendar
intervals and 'is when/where/why'. WordNet supplies a rough noun cue.
This is not a general parser: it uses fourteen tokens of history, resets
at document boundaries, and predicts zero outside the listed patterns.
"""
from functools import lru_cache
import wordnet

READS = ()
COPULA = {'is', 'are', 'was', 'were', 'be', 'been', "'s", '’s'}
SINGULAR = {'i', 'he', 'she', 'it', 'this', 'that'}
PRONOUNS = SINGULAR | {'you', 'we', 'they', 'there'}
MODALS = {'can', 'could', 'may', 'might', 'must', 'shall', 'should', 'will', 'would'}
CALENDAR_UNITS = {'day', 'week', 'month', 'year'}
INDEFINITE = {'something', 'anything', 'nothing', 'everything',
              'someone', 'anyone', 'everyone', 'somebody', 'anybody', 'nobody'}


@lru_cache(maxsize=4096)
def noun_subject(word):
    parts = wordnet.parts_of_speech(word)
    return 'noun' in parts and 'adverb' not in parts


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history, last_value = (), 0.0
