    raw = prefix.token_strings[-1]
    token = raw.strip()
    word = token.lower()
    prev = history[-1].strip().lower() if history else ''
    before = history[-2].strip().lower() if len(history) > 1 else ''
    recent = [s.strip().lower() for s in history[-12:]]
    tail = ''.join(history).lower().rstrip()
    # Uppercase IF in scientific names is not a conditional conjunction.
    distance = next((d for d, s in enumerate(history[::-1], 1)
                     if s.strip() in {'if', 'If'}), 100)
    conditional = distance <= 14
    suppose = tail.endswith('suppose') or any(
        tail.endswith('suppose ' + p) for p in PRONOUNS)
    near = distance <= 3 or suppose
