            elif prev == 'you':
                value = -7.4
            elif prev in {'they', 'we'}:
                value = -4.8
            elif prev == 'there':
                value = -6.0 if distance <= 3 else -2.0
            else:
                value = -4.0 if prev.endswith('s') else -9.0
                if distance > 4:
                    value = -6.0 if distance <= 8 else -3.0
            if prev in {'they', 'we', 'you'} and distance > 3:
                value *= 0.6
            if 'as' in recent[-4:]:
                value -= 1.0
        elif 'though' in recent[-3:]:
            value = -5.5 if prev in SINGULAR else -3.6
        elif token == 'Were' and (not history or not prev.isalpha()
                                  or raw[:1].isspace()):
            value = -2.5
        if word == 'weren':
            value *= 0.45
