    elif word == 'to' and prev in {'were', 'was', 'are'}:
        value = min(-2.0, 0.9 * last_value - 1.0) if prev == 'were' else -0.4
    elif prev == 'were' and token in {'I', 'he', 'she', 'it'}:
        value = -7.0 if word == 'it' else -4.0 if word == 'i' else -2.3
    elif word == 'had' and (near or 'wish' in recent[-3:]):
        value = -5.1 if prev == 'i' else -3.2 if prev in {'you', 'they', 'we'} else -1.9
    elif near and prev in PRONOUNS and word in {'could', 'wanted'}:
        value = -1.5 if word == 'could' else -3.0
    elif word == 'it' and (prev == 'try' or tail.endswith('think about')):
        value = -2.2
    elif token in {'I', 'he', 'she', 'it', 'you', 'we', 'they'}:
        if prev == 'if':
            value = -1.1 if token == 'I' else -0.2
        elif tail.endswith('suppose'):
            value = -2.2
    elif raw == ' be':
        if prev == 'need':
            value = -2.8
        elif prev in {'it', 'that', 'he', 'she'}:
            value = -3.2 if near or before == 'that' else -1.0
        elif prev not in MODALS and noun_subject(prev):
            value = -1.6 if 'that' in recent[-7:] else -0.65
    elif prev == 'need' and word in {'not', 'only'}:
        value = -7.0 if word == 'not' else -3.8
    elif raw in {' бы', ' б'}:
        value = -2.7 if word == 'бы' else -0.65
    elif raw == ' вы' and prev == 'если':
        value = -1.5
    elif word == 'case' and prev == 'the' and before in COPULA | {'not'}:
        value = -2.4 if before != 'were' else -5.0
    elif word == 'but':
        if prev in COPULA | {'had', 'have', "'tis"}:
            value = -3.2
        elif prev == 'wait':
            value = -2.6
        elif prev in {'help', 'including', 'all'}:
            value = -0.9
    elif word == 'instead' and tail.endswith('suppose'):
        value = -3.5
