    elif word in {'better', 'worse'}:
        if prev in COPULA | {'get', 'got', 'gotten', 'getting', 'much', 'even', 'damn'}:
            value = 1.0
    elif word == 'else' and prev in INDEFINITE:
        value = 2.1 if prev == 'something' else 1.3
    elif word in CALENDAR_UNITS and prev in {'every', 'per'}:
        value = 1.15 if prev == 'every' else 0.5
    elif word in {'when', 'where', 'why'} and prev in COPULA:
        value = 1.2
    return (doc, (history + (raw,))[-14:], value), value

programs.haiku:
"""Counterfactual ('were') mood: a strong negative response to the subjunctive
verb 'were' in hypothetical clauses -- 'if it were', 'if I were', 'if the graph
were', 'unless it were', 'as though he were' -- and to the words that go with
a hypothetical: 'were to', 'were it' (inverted 'Were it possible'), 'need not',
'Wait, but' (a self-correction), 'had' in an 'if' clause, 'Try it online', and
the Russian conditional particle 'бы'. Plural subjects after 'if' ('if they
were') and 'there were' are weaker. Indicative 'were' ('the results were') stays
near zero. Small positive values on 'better' and 'else'.
"""

READS = ()

IF_WORDS = {"if", "unless", "though", "imagine", "suppose"}
PLURAL = {"they", "there", "you", "we", "men", "changes"}
SOFT_WORDS = {"would", "even", "as"}
PRONOUNS = {"it", "i", "you", "he", "she", "one", "someone"}


def step(carry, prefix, upstream):
    toks = [s.strip().lower() for s in prefix.token_strings[-6:]]
    docs = prefix.document_ids[-6:]
    word = toks[-1]
    same = [t for t, d in zip(toks, docs) if d == docs[-1]]
    prev = same[-2] if len(same) > 1 else ""
    recent = same[-5:-1]  # the up-to-four tokens before this one, same document
    in_if = any(w in IF_WORDS for w in recent)

    if word in ("were", "weren"):
        if in_if:
            return None, -5.0 if prev in PLURAL else -10.0
        if prev in PRONOUNS or any(w in SOFT_WORDS for w in recent):
            return None, -2.5
        return None, 0.0
    if prev == "were" and word == "to":
        return None, -10.0 if in_if else -5.0
    if prev == "were" and word in ("it", "i", "this"):
        return None, -5.0
    if word in ("not", "be", "’t", "'t") and prev in ("need", "needn"):
        return None, -7.0
    if word == "but" and prev == "wait":
        return None, -2.6
    if word == "but" and prev in ("is", "was", "are", "has", "had", "am", "be"):
        return None, -3.0
    if word == "had" and in_if:
        return None, -2.5
    if word == "online" and prev == "it":
        return None, -5.5
    if word == "бы":
        return None, -1.7
    if word == "better":
        return None, 0.5
    if word == "else":
        return None, 0.3
    return None, 0.0

programs.sol:
"""An initial-token pulse, with scale estimated from readable token classes.

Training examples concentrate the large responses at row/document starts.
The pulse persists through an initial run of identical tokens, then switches
to zero. English grammar classes, word frequency, script and markup determine
its size; this approximates, rather than memorizes, token-specific variation.
"""
import regex
from wordfreq import zipf_frequency

READS = ()

BE_FORMS = set('am is are was were be been being'.split())
AUXILIARY = set(
    'do does did have has had can could may might must shall should '
    'will would'
    .split()
)
PREPOSITION = set(
    'of in on at by for from with into onto over under through between '
    'without within about against among around before after during '
    'until'
    .split()
)
PRONOUN = set('i you he she it we they me him us them'.split())
POSSESSIVE = set('my your his her its our their'.split())
CONJUNCTION = set(
    'and or but if so because as while although unless whether though '
    'than since'
    .split()
)
NUMBER = set('one two three four five six seven eight nine ten'.split())
DECLARATION = set(
    'def class function import package public private protected static '
    'const var let struct enum interface namespace include define'
    .split()
)
CODE_FLOW = set(
    'return void int string async await try catch raise throw using'.split()
)
QUESTION = set('who what where when why how which'.split())
NEGATION = set('no not never none neither cannot'.split())


def initial_value(s):
    t = s.strip()
    w = t.lower()
    if s.startswith('<|'):
        return 1.72
    if not t:
        if s == ' ':
            return -0.177
        return 3.538 if s.isspace() and '\n' not in s else 2.522
    if t.isdecimal():
        return -0.39
    if set(t) == {'#'}:
        return 9.897
    if t in ('//', '/*'):
        return 8.214 if '\n' in s else 13.13
    if t in ('"""', "'''"):
        return 10.573
    if t in ('"', "'"):
        return 1.783
    if t == ',':
        return 0.046
    if t == '.':
        return -1.16 if '\n' in s else 2.05
    if t in ('(', ')', '[', ']'):
        return 0.386
    if t in ('-', '--', '---'):
        return 4.61
    if '\ufffd' in t:
        return -0.815
    if regex.search(r'\p{Script=Han}|\p{Script=Hiragana}', t):
        return 0.826
    if not t.isascii():
        return 2.663 if t.isalpha() else 2.656
    if not t.isalpha():
        return 2.656
    if w in ('a', 'an', 'the'):
        if w == 'a':
            return 6.927 if s.startswith(' ') else 3.409
        return 10.279 if t.istitle() else 7.863
    if len(t) == 1:
        return 2.337 if t.isupper() else 2.466
    for words, value in (
        (BE_FORMS, 12.071), (AUXILIARY, 4.13),
        (PREPOSITION, 7.45), (PRONOUN, 4.386),
        (POSSESSIVE, 2.394), (CONJUNCTION, 5.552),
        (DECLARATION, 10.593), (CODE_FLOW, 7.432),
        (QUESTION, 6.389), (NEGATION, 7.396),
    ):
        if w in words:
            return value
    if w == 'to':
        return 2.562
    if w in NUMBER:
        return 14.115 if t.istitle() else 9.153
    f = zipf_frequency(w, 'en')
    if f < 3:
        return 3.018
    if f < 5:
        return 3.83
    return 6.385 if t.istitle() else 5.459


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    token = prefix.token_bytes[-1]
    if carry is None or carry[0] != doc:
        value = initial_value(s)
        return (doc, token, value), value
    doc, initial, value = carry
    if token == initial:
        return carry, value
    return (doc, None, 0.0), 0.0

