"""Layer-1 MLP unit that fires on the word that opens a new clause after a comma.

It reads the text so far and asks: is the current word a clause-linking word?
- Clause-linking words (but, so, which, then, however, whereas, including, ...) fire
  strongly right after a comma (", but", ", which") and weakly elsewhere.
- Coordinating conjunctions (and, or, nor, yet, as) fire after a comma only when the
  comma closes a full clause ("..., and it rained"), not when it sets off a list item
  ("cats, dogs, and"), where the unit is silent or slightly negative.
- Smaller triggers: "as well", the "e.g."/"i.e." piece, and foreign clause-linkers.
"""

READS = ()

STRONG = {"but", "so", "which", "who", "whom", "where", "whereas", "then", "however",
          "therefore", "thus", "hence", "though", "although", "while", "because",
          "otherwise", "including", "especially", "respectively", "such"}
ABBREV = {".g", ".e"}  # the middle pieces of "e.g." and "i.e."
CONJ = {"and", "or", "nor", "yet", "as"}
FOREIGN = {"которые", "который", "которая", "которое", "что", "hogy", "но", "pero", "aber",
           "wenn", "dass", "але", "但", "但是", "所以", "因此", "那么", "而", "并", "然而"}
BREAKS = {".", ";", ":", "!", "?", "\n"}


def clause_length(prefix, t):
    """Words since the previous comma or sentence break, before the comma at t-1."""
    n = 0
    for i in range(t - 2, max(-1, t - 60), -1):
        s = prefix.token_strings[i].strip()
        if s == "," or s in BREAKS:
            break
        if s:
            n += 1
    return n


def step(carry, prefix, upstream):
    t = prefix.position
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    after_comma = t > 0 and prefix.token_strings[-2].strip() == ","
    if word in STRONG:
        return carry, 1.4 if after_comma else 0.1
    if word in CONJ and after_comma:
        n = clause_length(prefix, t)
        return carry, 0.0 if n <= 2 else (0.35 if n <= 5 else 0.9)
    if word in CONJ:
        return carry, 0.0
    if word == "well":
        return carry, 0.35
    if word in ABBREV:
        return carry, 0.7
    if word in FOREIGN:
        return carry, 1.5 if after_comma else 0.2
    if after_comma and raw.strip() == "":
        return carry, 0.3
    return carry, 0.0

"""Candidate 5: feeling words, graded by intensity, and the preposition after them.
A feeling word used of a person (I am excited, so amazed, got used to) is strongly
negative, a copula use (is/was impressed) weakly, an attributive use (a comfortable
position) not at all. The preposition right after a feeling word (with, about, of, by)
is negative too. A few other words that govern a preposition (filled with, fond of) get a
weaker version."""
READS = ()

def words(s):
    return set(" " + w for w in s.split())

STRONG = words("""excited pleased amazed stunned fascinated puzzled thrilled bored saddened adamant
surprised delighted annoyed tired unsure glad grateful confident careful shocked disappointed""")
MEDIUM = words("""happy proud sorry afraid worried nervous confused impressed hooked upset stuck""")
WEAK = words("""concerned interested satisfied comfortable prepared inspired eager aware angry anxious
keen committed sure ready""")
FEELING = STRONG | MEDIUM | WEAK
GOV = words("""filled full fond educated married open forward faced armed hit captured influenced
joined opposed drawn dedicated hostile mindful ignorant passionate enthusiastic motivated known
hungry injured involved engaged related accustomed addicted attached responsible born""")
PERSON = words("am 'm ’m so very really feel get got getting not are 're ’re less more")
COPULA = words("is be been being was were")
TIER = {"strong": -5.0, "medium": -2.5, "weak": -1.2}
PREP_AFTER_FEEL = {" with": -3.1, " about": -3.1, " of": -1.8, " at": -1.7, " by": -1.4, " to": -0.4, " for": -0.35}
PREP_AFTER_GOV = {" with": -1.2, " about": -1.4, " of": -1.4, " at": -0.9, " by": -0.6, " to": -0.3, " for": -0.3}

