    "ug", "uga", "ugo", "ugi", "ugu", "ugas", "uger", "ugen", "ugin", "ugar", "UG",
    "rug", " rug", "hug", " hug", "drug", " drug", "Drug", " Drug", "drugs", " drugs",
    " Drugs", "lug", "ugged", "ugging",
]}

# Mid-word "u + ch" fragments switch the component off (below zero).
U_CH = {"луч": -4.0, "ча": -1.5, "уч": -1.0, "руч": -1.5, "вид": -1.5}

