"""Section- and snippet-boundary detector for layers.1.mlp.down_proj:5479.

Fires where one block of web or chat text ends and another begins:
  * a markdown heading marker (#, ##, ###) that starts a line: strong (about +0.9)
  * an ellipsis that cuts off a snippet ("...", "…"); stronger when a line ends right after it
  * bullets and the end of a reasoning block (</think>): weak
  * the newline that opens a chat turn: weak
  * line breaks in general: a faint positive baseline (about +0.05 for a single newline token, +0.09 for a blank line)
Negative on a long run of the middle-dot filler "··" (rare, very large when present).
Everything else predicts 0.
"""

READS = ()

HEADING = {'#', '##', '###', '####', '#####', '######'}
BULLETS = {'•', '●'}


def step(carry, prefix, upstream):
    run = carry if carry is not None else 0
    toks = prefix.token_strings
    tok = toks[-1]
    prev = toks[-2] if len(toks) > 1 else '\n'
    line_start = len(toks) == 1 or prev == '' or prev.endswith('\n')
    st = tok.strip()

    if tok == '··':
        run = run + 1 if prev == '··' else 1
        return run, (-1.8 if run >= 8 else 0.0)

    if st in HEADING:
        return 0, (0.9 if line_start else 0.1)
    if st.startswith('...') or st.startswith('…') or st.endswith('...') or st.endswith('…'):
        return 0, (0.9 if tok.endswith('\n') else 0.5)
    if st in BULLETS:
        return 0, 0.3
    if tok == '</think>':
        return 0, 0.25
    if tok in ('\n', '\n\n') and prev.strip() in ('user', 'assistant'):
        return 0, 0.2
    if tok == '\n\n':
        return 0, 0.09
    if tok == '\n':
        return 0, 0.05
    return 0, 0.0

