            return -7.5
        if tail.endswith('opti') and word.startswith('ch'):
            return -13.5
        if p.endswith('o') and word.startswith('ptic'):
            return -10.5
        if p.endswith('o') and word.startswith('pt'):
            return -6.0
        if prev.strip().lower() == 'оп' and word.startswith('ти'):
            return -13.5
        if prev.strip().lower() == 'оп' and word.startswith(('т', 'ц')):
            return -7.0
        if tail.endswith('опти') and word.startswith('ч'):
            return -13.5
