READS = ()
KNOWLEDGE = {'know', 'see', 'hear', 'read', 'learn', 'study', 'discuss',
             'talk', 'mention', 'say', 'remember', 'recall', 'understand',
             'notice', 'experience'}
BACKWARD = {'already', 'earlier', 'previously', 'before', 'above', 'previous'}
PERFECT = {'have', 'has', 'had', 've'}
AUXILIARIES = {'have', 've', 're', 'are', 'must', 'should', 'would', 'can',
               'could', 'will', 'll', 'had', 'might', 'may'}
POSSESSIVE = {'my', 'your', 'his', 'her', 'our', 'their', 'its'}
TIME = {'time', 'day', 'days', 'week', 'weeks', 'month', 'months', 'year', 'years'}
REFERENCE_VERBS = {'said', 'stated', 'noted', 'discussed', 'described',
                   'mentioned', 'shown', 'seen', 'did', 'used', 'found'}
# Small lexical offsets, followed below by the more important phrase rules.
WORD_BIAS = {
    'already': .47, 'earlier': .68, 'previously': .35,
    'before': .16, 'above': .05, 'previous': .13,
    'seen': .28, 'saw': .39, 'heard': .28, 'learned': .60,
    'discussed': .52, 'know': .12, 'familiar': .47,
    'mentioned': .09, 'noticed': .10, 'recall': -.15,
    'ago': .10, 'chapter': .13, 'course': .07,
}


@lru_cache(maxsize=50000)
def memory_word(word):
    if not word.isalpha() or len(word) > 25:
        return False
    return bool((set(wordnet.base_forms(word)) | {word}) & KNOWLEDGE)


def predict(history, token):
    s = token.strip().lower()
