            value += .84
        if s in {'done', 'said', 'experienced'} and {'all', 'we'} <= near:
            value += 1.95
        if s == 'case' and last in POSSESSIVE:
            value -= 1.10
        if s == 'course' and last == 'of':
            value += .58
        if s == 'previous' and last == 'our':
            value += 1.48
