    if t and len(set(t)) == 1 and '\n' not in s:
        ch, n = t[0], len(t)
        comment = bool(re.search(r'(?://|/\*|#)[-_=.*#/ ]*$', line)
                           or re.fullmatch(r'\s*--(?:\s[-_=.*#/ ]*)?', line))
        continuing = previous.endswith(ch) and not s[0].isspace()
        if ch == '·' and n >= 2:
            value = -1.36 if not tail.strip('·') else -0.1
        elif ch == '_' and n >= 8:
            value = (-2.7 if continuing and n >= 24 else -1.2) * min(1, n / 32)
            if comment and n >= 32:
