"""Layer-1 MLP component 5490: markup and separator lines in code comments.

What it does (activation in the component's own units, mostly zero):
- C# XML doc comments (lines starting with ///): the '<' that opens a tag is strongly
  negative (about -7), and so is the tag name: <summary> about -11, while <param>
  and <returns> are only about -1 to -2.
- Decorative rule lines: a run of 5 or more identical -, =, _, #, *, ., ~ characters.
  About -2 when it follows a comment opener (//, /*, #, --), about -0.4 otherwise.
- Python method decorators: the name after '@' is -7.5 for staticmethod and -5 for
  classmethod.
- The word PASS on a '--- PASS' test-runner line: about -1.
- The first token of each document: a small offset of about -0.2.
Everything else is zero; the component's remaining variance is diffuse and unexplained.
"""

READS = ()

RULE_CHARS = "-=_#*.~^/+"
COMMENT_OPENERS = ("//", "/*", "#", "--", "*", "/**", "///")
BRACKETS = ("<", "</")
DECORATORS = {"staticmethod": -7.5, "classmethod": -5.0}


def is_rule(bare):
    """A run of at least five copies of one rule character, e.g. '-----' or '=====' ."""
    return len(bare) >= 5 and bare[0] in RULE_CHARS and bare == bare[0] * len(bare)


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    bare = tok.strip()
    if carry is None or prefix.document_ids[-1] != carry["doc"]:
        # First token of a document: reset the line state and apply the start offset.
        carry = {"doc": prefix.document_ids[-1], "lead": "", "prev": ""}
        value = -0.2
    else:
        value = 0.0
    lead, prev = carry["lead"], carry["prev"].strip()
    if lead.startswith("///"):
        if bare in BRACKETS:
            value = -7.0
        elif prev in BRACKETS and bare == "summary":
            value = -11.0
        elif prev in BRACKETS and bare in ("param", "returns"):
            value = -1.5
    elif is_rule(bare):
        value = -2.0 if prev in COMMENT_OPENERS else -0.4
    elif bare in DECORATORS and prev == "@":
        value = DECORATORS[bare]
    elif bare == "PASS" and lead.startswith("---"):
        value = -1.0
    # Track the current line (its leading text) for the next position.
    if "\n" in tok:
        lead = tok.split("\n")[-1]
    else:
        lead = lead + tok
    lead = lead.lstrip()[:4]
    return {"doc": carry["doc"], "lead": lead, "prev": tok}, value

