    ('es', 'tu tus', -1.5),
    ('fr', 'mon ma ton ta son sa', -1.35),
    ('fr', 'mes tes ses nos', -0.7),
    ('fr', 'notre', -1.1),
    ('fr', 'votre leur', -1.55),
