        else:
            run = max(map(len, re.findall(r'\\+', token)))
            value = 1.5 if run == 2 else 0.57 if run == 3 else 1.1
    return (doc, (tail + token)[-400:]), float(value)

programs.haiku:
"""Layer 1, MLP down-projection component 5492.

What it responds to: nouns for a change or difference in an amount (increase, decrease,
rise, fall, reduction, gap, difference, shift, trend, correlation, change) and nouns for a
lack, need or sense (need, lack, sense, desire, presumption, emphasis), when they stand in
an indefinite phrase: "an increase", "a significant decrease", "a need", "no need",
"a sense", "a period". Such a noun is strongly negative, and so is the preposition that
opens its complement ("an increase [in]", "a change [in]", "a loss [of]"). Weaker
amount and relation nouns (relationship, effect, level, range, rate, risk) give a
smaller negative value. A percent sign after a number is mildly negative ("25%").
The same nouns after "the", or used as verbs, are near zero, and so is everything else.

The program predicts a fixed value for each case, taken from the component's average
activation in that case, using only the current token and the tokens before it.
"""

READS = ()

INDEFINITE = {
    "a", "an", "no", "any", "such", "another", "%",
    "significant", "marked", "big", "large", "small", "short", "strong", "positive",
    "negative", "wide", "further", "total", "sharp", "slight", "sudden", "dramatic",
    "substantial", "modest", "steady", "gradual", "rapid", "considerable", "major",
    "massive", "qualitative", "growing", "increasing",
}
# Change-in-amount and need/lack nouns: strong.
CHANGE_NOUNS = {
    "increase", "increases", "decrease", "decreases", "change", "rise", "fall", "drop",
    "reduction", "improvement", "decline", "gap", "difference", "differences", "shift",
    "trend", "correlation", "period", "gain", "loss", "majority", "lack", "need", "sense",
    "desire", "presumption", "emphasis", "focus", "saving", "profit", "halt", "demand",
    "attempt", "effort", "preference", "failure", "recovery", "feeling",
}
# Weaker amount, relation and degree nouns.
RELATION_NOUNS = {
    "relationship", "effect", "effects", "impact", "range", "changes", "growth", "level",
    "portion", "association", "connection", "link", "degree", "basis", "risk", "cost",
    "factor", "rate", "history", "benefit", "interest", "limit", "response", "role",
    "influence", "return", "balance", "investment", "tax", "fee", "average", "maximum",
    "amount", "proportion", "advantage", "burden", "chance", "price",
}
COMPLEMENT_PREPS = {"of", "in", "to", "for", "toward", "towards", "between"}


def _word(prefix, back):
    """The token `back` steps before the current one, lowercased and stripped ('' if none
    or if it lies in another document)."""
    i = len(prefix.token_ids) - 1 - back
    if i < 0 or prefix.document_ids[i] != prefix.document_ids[-1]:
        return ""
    return prefix.token_strings[i].strip().lower()


def _indefinite(prefix, back):
    """Whether the noun `back` tokens before the current one follows an indefinite
    article, 'no', or a modifier such as 'significant'."""
    return _word(prefix, back) in INDEFINITE or _word(prefix, back + 1) in ("a", "an", "no")


def step(carry, prefix, upstream):
    word, before = _word(prefix, 0), _word(prefix, 1)
    if word in CHANGE_NOUNS or word in RELATION_NOUNS:
        indefinite = _indefinite(prefix, 1)
        if word in CHANGE_NOUNS:
            value = -2.2 if indefinite else 0.0
        else:
            value = -0.9 if indefinite else 0.0
    elif before in CHANGE_NOUNS or before in RELATION_NOUNS:
        # A complement preposition right after a change or relation noun.
        indefinite = _indefinite(prefix, 2)
        if before in CHANGE_NOUNS and word == "in":
            value = -3.0 if indefinite else -1.2
        elif before in CHANGE_NOUNS and word in ("of", "for"):
            value = -1.5 if indefinite else -0.4
        elif before in CHANGE_NOUNS and word == "to":
            value = -1.3 if indefinite else 0.0
        elif before in RELATION_NOUNS and word in COMPLEMENT_PREPS:
            value = -0.5 if indefinite else 0.0
        else:
            value = 0.0
    elif word == "%" and before[:1].isdigit():
        value = -0.3  # "25%": the percent sign after a number
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Detect von-like spellings and certain uses of the preposition 'on'.

German von/vom and English on after calling, drawing, or reliance are
positive. Short o-nasal fragments after v/y are also positive; short
u-fragments after those letters are negative. Most tokens predict zero.
This is a spelling-and-local-phrase approximation, not a semantic analysis.
"""
import re
import regex
from anyascii import anyascii

READS = ()
SUMMON = r'\b(call(?:s|ed|ing)?|draw(?:s|ing)?|drew|count(?:s|ed|ing)?)\s*$'
RELY = r'\b(rely|relies|relied|relying)\s*$'
DEPEND = r'\bdepend(?:s|ed|ing)?\s*$'
DISTANT = (
    r'\b(rely|relies|relied|relying|relian\w*|depend\w*)'
    r'\b[^.!?\n]{0,24}$'
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, recent = '', ''
    else:
        _, previous, recent = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    s, p = word.lower(), previous.lower()
    spaced = token[:1].isspace()
    value = 0.0

    if s in ('von', 'vom', 'davon'):
        value = 3.0 if spaced else 6.3
        if word[:1].isupper():
            value = 8.0
    elif s in ('on', 'upon') and spaced:
        if re.search(SUMMON, recent, re.I):
            value = 6.0
        elif re.search(RELY, recent, re.I):
            value = 2.5
        elif re.search(DEPEND, recent, re.I):
            value = 1.7
        elif re.search(DISTANT, recent, re.I):
            value = 0.9
    elif s in ('yon', 'xon', 'yong') or re.search(r'[vy]on$', s):
        value = 2.7
    elif re.fullmatch(r'on(?:d|s|g|ian)?|om', s) and not spaced:
        if p.endswith(('v', 'y')):
            if s == 'ons':
                value = 1.2
            elif s == 'om':
                value = 2.4
            else:
                value = 6.5 if s in ('on', 'ond') else 4.5
            if word.istitle():  # Camel-case code, e.g. spy + On.
                value = 0.5
        elif p.endswith(('w', 'x')) and s == 'on':
            value = 0.65
    elif s in ('vu', 'vul', 'vuel'):
        value = -1.8
    elif s == 'yu':
        value = -6.6
    elif s.startswith('u') and not spaced and word.isalpha():
        if p.endswith(('v', 'y')) and (word.islower() or word.isupper()):
            if len(s) == 1:
                value = -4.8
            elif s in ('ue', 'ui'):
                value = -4.0
            elif len(s) <= 3:
                value = -2.0
            elif len(s) == 4:
                value = -1.3
    elif s == 'et' and not spaced and p.endswith(('v', 'y')):
        value = 1.6
    elif s in ('vet', 'veto', 'veterinary', 'veterinarian'):
        value = 1.9
    elif s == 'yet':
        value = 0.2
    elif s == 'ゆ':  # Hiragana yu.
        value = -2.8
    elif not spaced and regex.fullmatch(r'\p{Script=Cyrillic}+', s):
        # The corresponding split Cyrillic vo-n spelling.
        if anyascii(s).lower() == 'on':
            if anyascii(p).lower().endswith('v'):
                value = 4.0

    return (doc, token, (recent + token)[-100:]), value

programs.haiku:
"""Layer 1, MLP output unit 5493: a German/Dutch "von" name-particle detector.

What it responds to, in plain terms:
- The particle "von" (and "vom", "davon"). It is strongest when "von" is a name particle
  ("Alexander von", "Emil von") or a capitalised "Von" / "von" token, and weak when it
  means "of" after a noun ending in -ung or -ion ("Anzahl von").
- "on" that completes a split "von"-like word: a piece ending in "v" or "y" followed by "on"
  ("Av|on", "V|on", "y|on"). Also "xon" and "yon" pieces.
- "on" or "upon" right after a verb of calling, drawing on or relying on something:
  "count on", "call on", "draw on", "rely on", "depend on", "build on".
- Negative on the "u" twin of "von": "Yu", "Vu", and the kana "ゆ"/"ユ" (the sound "yu").

Everything else is predicted as 0. The program looks only at the current token and the
word before it; it keeps no state.
"""

READS = ()

# "von" as a word or name particle, by how it is written (token -> activation)
VON_NAME = {" Von", "Von", "von"}
VON_WORD = {" von": 3.0, " vom": 3.0, " davon": 3.0, " Devon": 3.0, "xon": 2.5, "yon": 2.5}

# the "u" twin of "von": negative
NEG = {" Yu": -5.0, "yu": -5.0, "Yu": -5.0, "ゆ": -3.4, "ユ": -1.4,
       " Vu": -3.0, "vu": -2.0, " vu": -2.0, " vul": -2.0, "vue": -2.0}

# verb stems (lower case, start of the previous word) -> activation on the "on" / "upon" after it
ON_AFTER = {"call": 6.0, "count": 6.0, "draw": 6.0, "drew": 6.0, "rely": 2.7, "relie": 2.7,
            "relian": 1.2, "lean": 2.7, "depend": 1.1, "build": 1.7, "built": 0.8, "bet": 0.8}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if tok in VON_NAME:
        return None, 7.0
    if tok == " von" and prev.endswith(("ung", "ion")):
        return None, 1.8
    if tok in VON_WORD:
        return None, VON_WORD[tok]
    if tok in NEG:
        return None, NEG[tok]
    if tok == "on" and prev.endswith(("v", "av", "ray")):
        return None, 7.0
    if tok == "on" and prev.endswith("y"):
        return None, 3.0
    if tok in (" on", " upon", "on"):
        for stem, value in ON_AFTER.items():
            if prev.startswith(stem):
                return None, value
    return None, 0.0

programs.sol:
"""A sparse surface-text approximation, not a lexical lookup.

Negative rules cover Braille spinner prefixes, split private-use glyphs,
a reversed-sigma symbol, repeated Cyrillic mojibake, and Thai text amid
C1 controls. Small baselines model document openings and UTF-8 continuation
bytes. Opening title delimiters and interpunct fillers are positive;
tool-call openers are negative. Ordinary text is otherwise zero.
State holds the document-relative position and the last 256 bytes.
Remaining lexical and contextual variation is not modeled.
"""
import unicodedata

READS = ()
# Characteristic prefixes produced by misdecoding UTF-8 as Cyrillic.
MOJIBAKE_PREFIXES = frozenset('ГЕпЛ')


def corrupted_cyrillic(text):
    repaired = text.encode('cp1251', 'ignore').decode('utf-8', 'ignore')
    return sum(ord(c) > 127 for c in repaired) >= 2


def opening(text, raw):
    if text == '<|im_start|>':
        return -0.23
    if not text:
        return 0.13 if raw.startswith(b' ') else 0.04
    if len(text) == 1:
        if text.istitle() and text.isascii():
            return 0.21
        if text.isalpha() and text.isascii():
            return -0.09
        return 0.05
    if text.isascii() and text.isalpha():
        if len(text) <= 3:
            return 0.36 if text.istitle() else 0.20
        return 0.20 if raw.startswith(b' ') else 0.14
    if any(unicodedata.category(c).startswith('S') for c in text):
        return -0.17
    return 0.07


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    history, position = (b'', 0) if start else (carry[1], carry[2])
    b = prefix.token_bytes[-1]
    text = b.decode('utf-8', 'ignore').strip()
    old = history.decode('utf-8', 'ignore')
    value = opening(text, b) if start else 0.0

    if not start and 0x80 <= b[0] < 0xC0:
        value = -0.05
    if text == '<tool_call>':
        value = -0.15
    elif position == 1 and old == 'Title' and text == ':':
        value = 3.2
    elif len(text) >= 2 and set(text) == {'·'}:
        value = 0.45
    # U+2800--U+283F: Braille cells, often used as terminal spinners.
    elif b'\xe2\xa0' in b:
        value = -0.7
    # Second byte of a private-use font glyph, split by UTF-8 band.
    elif history.endswith(b'\xee') and len(b) == 1:
        value = -0.18 if b[0] < 0xA0 else -0.8
    elif b.strip() == b'\xee':
        value = -0.12
    elif text and 'REVERSED LUNATE SIGMA' in unicodedata.name(text[0], ''):
        value = -1.1
    elif text in MOJIBAKE_PREFIXES:
        alphabet = {c for c in old
                    if unicodedata.name(c, '').startswith('CYRILLIC')}
        if len(alphabet) <= 8 and corrupted_cyrillic(old):
            value = -0.7
    elif not b.isascii():
        controls = any(0x80 <= ord(c) <= 0x9f for c in old)
        if controls and (b.strip() == b'\xe0\xb9' or
                         history.endswith(b'\xe0\xb9') and
                         0x80 <= b[0] < 0xC0):
            value = -1.4
        elif controls and text and all(
            unicodedata.name(c, '').startswith('THAI') for c in text
        ):
            value = -0.4

    return (doc, (history + b)[-256:], position + 1), value

"""Approximate a response to changes in size, speed, strength and other properties.

English fires chiefly on 'the' following a change verb (e.g. 'reduce the').
Chinese fires on change words and on scalar adjectives completing a causative
or degree construction. Completing a split word usually gets a larger response
than reading a whole compound. Dictionaries supply inflections and meanings.
Reduplicated Chinese size adjectives get a negative response. The short byte
buffer resets at document boundaries and also handles split UTF-8 characters.
"""
from functools import lru_cache
import re
import regex
import wordnet
import cedict
from opencc import OpenCC

READS = ()
SIMPLIFY = OpenCC('t2s').convert
# English transitive changes, roughly from strongest to weakest.
VERBS = (
    (1.8, 'reduce lower diminish shorten shrink'),
    (1.4, 'increase raise enlarge expand extend prolong broaden narrow'),
    (1.3, 'change alter vary transform break reverse'),
    (0.7, 'adjust shift switch turn'),
    (0.15, 'modify amend revise edit'),
    (0.2, 'open close'),
)
# Opposites along familiar scalar dimensions.
DIMENSIONS = {
    'size': '大小', 'height': '高低', 'vertical': '升降',
    'length': '长短', 'speed': '快慢缓急', 'strength': '强弱重轻',
    'quality': '好坏', 'quantity': '多少',
    'other': '深浅宽窄厚薄亮暗黑白软硬松紧冷热暖凉',
}
DIMENSION = {c: name for name, chars in DIMENSIONS.items() for c in chars}

@lru_cache(maxsize=8192)
def english(word):
    roots = set(wordnet.base_forms(word, 'verb'))
    for value, names in VERBS:
        if roots.intersection(names.split()):
            return value
    return 0.04 if 'verb.change' in wordnet.categories(word, 'verb') else 0.0

@lru_cache(maxsize=16384)
def chinese(word):
    glosses = cedict.glosses(word)
    if not glosses:
        return 0.0
    first = glosses[0]
    if 'innovation' in glosses:
        return 1.0
    if 'earlier date' in first:
        return 2.1
    if any(s in first for s in ('loan', 'breed', 'animals', 'issue', ' into')):
        return 0.0
    m = re.match(r'to ([a-z]+)\b', first)
    if not m:
        return 0.0
    if m[1] in {'increase', 'decrease', 'reduce', 'raise', 'lower', 'expand',
                'extend', 'shrink', 'prolong', 'lift', 'elevate', 'rise',
                'ascend', 'descend', 'fall', 'slow'}:
        return 0.55
    if m[1] in {'intensify', 'strengthen', 'accelerate', 'enhance', 'improve',
                'widen', 'weaken', 'enlarge', 'heighten', 'hasten', 'deepen',
                'aggravate', 'reinforce'}:
        return 0.4
    if m[1] in {'change', 'alter', 'transform', 'adjust', 'break'}:
        return 0.4
    return 0.0


def chinese_context(before, current):
    current, before = SIMPLIFY(current).strip(), SIMPLIFY(before[-8:])
    text, start = before + current, len(before)
    for j in range(len(text)-1, max(0, start-1), -1):
        if text[j] not in DIMENSION or any(c not in '的了对力' for c in text[j+1:]):
            continue
        kind, marker, split = DIMENSION[text[j]], text[j-1], j == start
        # Add/intensify; lengthen/stretch; become.
        if marker == '加':
            if kind == 'size':
                return 6.0 if split else 5.7
            if kind == 'speed':
                return 3.8
            return 4.0 if split else 2.0
        if marker in '延拉' and kind == 'length':
            return 6.0 if split else 2.9
        if marker == '变':
            return 4.0
        # Increase, reduce, shrink, expand, raise, lower, and resultative actions.
        if marker in '增减缩扩提升降放调抹擦收':
            if kind == 'length':
                return 6.0 if split else 0.5
            if kind == 'vertical':
                return 3.0 if split else 1.5
            if kind == 'quantity':
                return 2.5 if split else 1.7
            if kind == 'size':
                return 5.0 if split else 3.5
            if kind == 'height':
                return 3.7 if split else 2.6
            return 3.5 if split else 1.3
        # Degree modifiers: more, relatively, excessively, somewhat, very.
        if marker in '越较过偏更太很':
            if not split:
                return 0.3 if kind == 'size' else 0.05
            if kind == 'speed':
                return 2.0
            return 0.5 if kind == 'strength' else 1.1
    for length in (len(current), 3, 2):
        if length >= 2 and length <= len(text):
            value = chinese(text[-length:])
            if value:
                return value
    if current == '了' and any(chinese(before[-n:]) for n in (3, 2, 1)):
        return 1.5
    if current in {'大大', '小小'}:
        return -1.4
    return 0.4 if current in set('快慢缓急') else 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_bytes[-1]
    old = carry[1] if carry is not None and carry[0] == doc else b''
    before = old.decode('utf-8', 'ignore')
    # Joining bytes also completes a Han character split across tokens.
    current = (old + token).decode('utf-8', 'ignore')[len(before):]
    value = 0.001
    if token == b' the':
        m = re.search(r'([A-Za-z]+)$', before)
        value = english(m[1].lower()) if m else 0.0
    elif regex.search(r'\p{Script=Han}', current):
        value = chinese_context(before, current)
    return (doc, (old + token)[-96:]), float(value)

"""Approximate a mixed abbreviation / source-code naming feature.

US is strongly negative at word boundaries. GitHub owner boundaries and
selected software namespace segments are positive. There are separate
rules for PHP/C# declarations, documentation tags and heading punctuation.
Everything else gets zero. A 400-character suffix supplies context and is
reset at document boundaries; there is no token-ID lookup table.
"""
import re

READS = ()


def activation(token, before):
    word = token.strip()
    boundary = not before or not before[-1].isalpha()

    # Abbreviations and their spelling pieces, with weaker inside-word US.
    if word == '-US':
        return -2.0
    if word == 'US':
        if token.startswith(' '):
            return -4.0
        return -4.8 if boundary else -0.4
    if word in ('UN', 'EP', 'ISS'):
        if token.startswith(' ') or boundary:
            return -1.0
    if word.lower().strip('_.') == 'ip':
        if word != 'ip' or boundary or token.startswith(' '):
            return -0.65
    if word in ('us', 'Us') and not token.startswith(' ') and boundary:
        return -2.4 if word == 'us' else -0.7

    # Namespace and import declarations in PHP and C# have negative signs.
    if word == 'namespace' and re.search(r'(?:^|\n)\s*\Z', before):
        if '<?php' in before:
            return -10.8
        return -2.6 if 'using ' in before else -0.8
    if word in ('use', 'class') and re.search(r'(?:^|\n)\s*\Z', before):
        if '<?php' in before or re.search(
                r'(?:namespace|use) [^;\n]*\\', before):
            return -4.5 if word == 'use' else -2.3

    # GitHub owners and reverse-domain package segments are positive.
    if token.startswith('/') and before.endswith('github.com'):
        if before.endswith('api.github.com'):
            return 1.8
        return 4.3 if token == '/' else 2.7
    if re.fullmatch(r'[./][A-Za-z][A-Za-z_]*', token):
        root = re.search(
            r'(?:^|[^A-Za-z_])'
            r'(com|org|net|io|android|java|javax|System|Microsoft)\Z', before)
        if root:
            name = token[1:]
            if name == 'example':
                return 4.5
            if name == 'google':
                return 3.0
            if name == 'apache':
                return 2.0
            if root[1] in ('com', 'org', 'net', 'io'):
                return 0.8
            if root[1] == 'System' and name == 'Text':
                return 1.8
            return 0.15

    # Documentation and heading conventions.
    if word == 'Tags' and before.endswith('Show'):
        return -2.9
    if word == 'generated' and before.rstrip().endswith('@'):
        return 3.0
    if word == 'The' and re.search(r'Copyright[^\n]{0,40}\Z', before, re.I):
        return 5.0
    if token == ':' and re.search(r'(?:^|<\|endoftext\|>)Title\Z', before):
        return -4.3
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, (before + token)[-400:]), activation(token, before)

"""Approximate SQL syntax and identifier-boundary pulses.

Recent query/schema markers gate clause words, types, qualified column names,
and identifier delimiters, particularly MySQL backticks. Android's R.id and a
few literal formatting cues are handled separately. Other text stays near zero.
State resets per document; this is a local heuristic, not a complete SQL parser.
Command starts need a line/string boundary or uppercase spelling. Schema and
insertion context starts only after the TABLE/DATABASE and INTO continuations.
"""
import re

READS = ()
INTEGERS = {'int', 'integer', 'bigint', 'smallint', 'tinyint'}
TYPES = INTEGERS | set('''varchar nvarchar char nchar
text date datetime timestamp decimal numeric float double boolean bool serial
blob binary real'''.split())
AGGREGATES = {'count', 'sum', 'avg', 'min', 'max'}
CLAUSES = {'from': 2.5, 'as': 2.9, 'and': 1.35, 'where': 0.75,
           'on': 0.75, 'set': 0.15, 'default': 0.6, 'not': 0.6}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pos, previous, query_at, schema_at, insert_at = 0, '', -1000, -1000, -1000
        query_kind = ''
        line_blank = True
        last_start = False
    else:
        (_, pos, previous, query_at, schema_at, insert_at,
         query_kind, line_blank, last_start) = carry
        pos += 1
    word, prev = s.strip().lower(), previous.strip().lower()
    # Camel-case fragments such as "As" in "Asignacion" aren't SQL keywords.
    raw, old = s.strip(), previous.strip()
    key = word if raw.islower() or raw.isupper() else ''
    prior = prev if old.islower() or old.isupper() else ''
    command = key in {'select', 'update', 'delete', 'insert',
                      'create', 'alter', 'drop', 'use'} and (
            s.strip().isupper() or line_blank
            or prev in {'("', "('", '"', "'", '`'})
    if command:
        if key in {'select', 'update', 'delete'}:
            query_kind, query_at = key, pos
        elif key == 'use':
            schema_at = pos
    if word == '.append' and prev == 'sql':
        query_at = pos
    if key == 'from' and (raw.isupper() or prev in {'*', '.*'}):
        query_at = pos
    if (key in {'table', 'database'} and s[:1].isspace()
            and prior in {'create', 'alter', 'drop'} and last_start):
        schema_at = pos
    if key == 'references' and prev == ')' and (
            raw.isupper() or pos-schema_at < 160 or pos-query_at < 80):
        schema_at = pos
    if (key == 'into' and prior == 'insert' and s[:1].isspace()
            and last_start):
        insert_at = pos
    if key == 'values':
        insert_at = -1000
    query, schema = pos - query_at < 80, pos - schema_at < 160
    sql = query or schema or pos - insert_at < 80
    if '\n' in s:
        line_blank = not s.rsplit('\n', 1)[1].strip()
    elif s.strip():
        line_blank = False
    state = (doc, pos, s, query_at, schema_at, insert_at,
             query_kind, line_blank, command)

    value = 0.0
    if len(word) >= 2 and set(word) == {'·'} and not s.startswith(' '):
        value = -1.8
    elif word == ':' and prev == 'title' and pos == 1:
        value = 8.38
    elif word == 'php' and prev == '<?':
        value = 1.59
    elif key == 'into' and prior == 'insert' and pos == insert_at:
        value = 6.9
    elif key == 'from' and prior == 'delete' and query_kind == 'delete' and query:
        value = 10.0
    elif key == 'from' and prev in {'*', '.*'} and query:
        value = 5.5
    elif key == 'set' and query and query_kind == 'update':
        value = 5.0
    elif key == 'null' and prior == 'not' and s[:1].isspace():
        value = 4.8 if schema else 3.2
    elif key == 'references' and schema:
        value = 5.5
    elif key == 'table' and prior in {'create', 'alter'} and pos-schema_at <= 2:
        value = 3.0
    elif word == '.id' and re.search(r'(?<!\w)R$', previous):
        value = 6.0  # Android's R.id resource identifiers.
    elif word == '.id':
        value = 4.0 if query else 0.3
    elif sql:
        if word in {'`', '(`'}:
            if word == '(`':
                value = 8.0
            elif not s[:1].isspace():
                value = 2.0
            elif prior in {'table', 'database', 'into', 'from', 'use',
                          'join', 'exists'}:
                value = 10.5
            elif query and prior in {'where', 'and', 'or', 'by'}:
                value = 8.0
            else:
                value = 5.0 if schema else 3.5 if query else 3.0
        elif schema and prev == '`' and key in TYPES:
            value = 7.5 if key in INTEGERS else 4.5
        elif word.startswith('(') and pos - insert_at < 24:
            value = 6.0
        elif key in CLAUSES:
            value = CLAUSES[key]
        elif key in AGGREGATES:
            value = 2.0
        elif schema and key in TYPES:
            value = 1.35
        elif word in {'[', '"', '([', '("'}:
            value = 3.0 if schema else 0.6
        elif word.startswith('('):
            value = 1.35 if schema else 0.15
        elif re.fullmatch(r'\.[A-Za-z_][A-Za-z_0-9]*', word):
            value = 2.0 if query and prev.isalnum() and len(prev) <= 2 else 0.3
        elif query and key.isalpha() and len(key) <= 2 and prior in {
                'select', 'from', 'and', 'join', 'by', 'on'}:
            value = 1.5
        elif word in {'*', '.*'}:
            value = 1.3
        elif word == ',' and query:
            value = 0.35
        elif '\n' in s:
            value = 0.15
    return state, float(value)

programs.haiku:
"""Component layers.1.mlp.down_proj:5497: a SQL-statement feature.

The component stays near zero on ordinary text. Once a document contains an actual SQL
statement (CREATE TABLE, INSERT INTO, DELETE FROM, UPDATE ... SET, ALTER TABLE, FOREIGN KEY,
AUTO_INCREMENT), it turns on for the tokens that build that statement:

- clause words: INTO, FROM, REFERENCES, TABLE, AS, AND, SET, WHERE, ON, VALUES (about 4);
- column types and constraints: NULL, int, varchar, INTEGER, CHAR, DATE, DEFAULT, KEY (about 2.5);
- the opening quote of a quoted identifier, a backtick or a square bracket, which starts a
  table or column name (about 5).

Two corpus artifacts are predicted directly: a run of middle dots (a filler line) is -1.8, and
the colon of a "Title:" header right after a document separator is 8.4.
"""

import re

READS = ()

# Phrases that mean the document holds real SQL code.
SQL_STATEMENT = re.compile(
    r"\b(create\s+table|insert\s+into|delete\s+from|update\s+\w+\s+set|alter\s+table"
    r"|foreign\s+key|auto_increment)\b",
    re.IGNORECASE,
)

CLAUSE_WORDS = {" INTO", " FROM", " from", " REFERENCES", " TABLE", " AS", " AND", " SET",
                " WHERE", " ON", " VALUES"}
COLUMN_WORDS = {" NULL", " null", " int", " INTEGER", " varchar", " VARCHAR", " CHAR", " DATE",
                " DEFAULT", " KEY", " key"}
IDENTIFIER_OPENERS = {" `", " (`", "`", " [", "[", " (["}


def step(carry, prefix, upstream):
    # carry: (document id, whether this document has shown SQL, recent text)
    doc = prefix.document_ids[-1]
    tok = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        in_sql, recent = False, ""
    else:
        _, in_sql, recent = carry
    header = tok == ":" and recent.endswith("<|endoftext|>Title")
    recent = (recent + tok)[-200:]
    if not in_sql and SQL_STATEMENT.search(recent):
        in_sql = True

    value = 0.0
    if in_sql:
        if tok in CLAUSE_WORDS:
            value = 4.0
        elif tok in COLUMN_WORDS:
            value = 2.5
        elif tok in IDENTIFIER_OPENERS:
            value = 5.0
    if tok and set(tok) == {"·"}:
        value = -1.8
    if header:
        value = 8.4
    return (doc, in_sql, recent), value

programs.sol:
"""A negative marker for a document's first, still-unvaried token run.

The marker is strongest for unspaced Latin words and comment/heading marks,
weaker for whitespace and ordinary punctuation. Once different tokens arrive,
only a small, rapidly fading negative background remains. Token-shape averages
approximate the marker's token-specific strength; they do not identify words.
"""
import math
from functools import lru_cache
import regex

READS = ()


@lru_cache(maxsize=16384)
def initial_strength(s):
    t = s.strip()
    if s.startswith('<|'):
        return -2.5
    if not t:
        if s == ' ':
            return -1.35
        if not s.strip('\r\n'):
            return -1.74
        return -2.46 if '\t' in s else -2.2
    if t.isdecimal():
        return -2.23
    if t.isascii() and t.isalpha():
        if s[0].isspace():
            return -2.08
        if t.istitle():
            return -3.36
        return -3.0 if t.isupper() else -2.67
    if regex.search(r'\p{Script=Han}', t):
        return -2.03
    if not t.isascii() and regex.search(r'\p{Script=Latin}', t):
        return -1.71
    if any(c.isalpha() for c in t):
        return -2.38
    if s[0].isspace():
        return -1.68
    if not t.isascii():
        return -1.59
    if t.startswith(('#', '//', '/*')):
        return -3.3
    if any(c in '{}[]()' for c in t):
        return -1.82
    if t.startswith(('"', "'", '`')):
        return -2.22
    if t.startswith(('.', ',', ':', ';')):
        return -1.57
    return -2.21


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    if carry is None or carry[0] != doc:
        age, first, same = 0, raw, True
    else:
        _, age, first, same = carry
        age += 1
        same = same and raw == first
    value = (initial_strength(token) if same else
             -0.006 - 0.068 * math.exp(-age / 20.0))
    return (doc, age, first, same), float(value)

programs.haiku:
"""Initials inside a list of author names (reference lists).

Component layers.1.mlp.down_proj:5499 is silent almost everywhere. It responds to a single
capital letter used as an initial, such as the "M" in "Papandreou I, Sutphin P D" or the
"J" in "Smith B J, ...", when that initial sits inside a bibliography-style list of
person names: several surnames and initials separated by commas, a few tokens back.

Two things in the preceding 10 tokens of the same document set its size:
  - how many name-like tokens there are (capitalised words or initials), peaking at
    about 4-5, i.e. a short run of "Surname Initial," entries;
  - how many commas there are, peaking at about 2.

The program: if the current token is a single capital letter, predict a bump
exp(-((names - 4.8) / 1.6)^2 / 2 - (commas - 2.2)^2 / 2) scaled to 1.2; otherwise 0.
Everything else (ordinary words, digits, capitalised words that are not initials) is 0.
"""

import math
import string

READS = ()

WINDOW = 10
NAME_CENTRE, NAME_WIDTH = 4.8, 1.6
COMMA_CENTRE, COMMA_WIDTH = 2.2, 1.0
AMPLITUDE = 1.2


def _core(text):
    return text.strip(" .,;()[]\n\t•-")


def _is_initial(text):
    core = _core(text)
    return len(core) == 1 and core in string.ascii_uppercase


def _is_name_like(text):
    core = _core(text)
    return core.isalpha() and core[0].isupper()


def _bump(value, centre, width):
    return math.exp(-0.5 * ((value - centre) / width) ** 2)


def step(carry, prefix, upstream):
    t = prefix.position
    docs = prefix.document_ids
    strings = prefix.token_strings
    if not _is_initial(strings[t]):
        return carry, 0.0
    names = 0
    commas = 0
    for j in range(max(0, t - WINDOW), t):
        if docs[j] != docs[t]:
            continue
        if _is_name_like(strings[j]):
            names += 1
        if strings[j].strip() == ",":
            commas += 1
    value = AMPLITUDE * _bump(names, NAME_CENTRE, NAME_WIDTH) * _bump(commas, COMMA_CENTRE, COMMA_WIDTH)
    return carry, float(value)

programs.sol:
"""Detect exposed spellings of chain and link, not connections in general.

A short byte suffix lets a word or a Chinese character cross token boundaries.
Whole tokens containing a longer compound usually respond much less than an
exposed stem. Chain vocabulary is stronger than ordinary link vocabulary.
The constants approximate category means; unrelated activity is left at zero.
"""
import re

READS = ()
ENGLISH = re.compile(r"chain(?:ed|ing|s)?|link(?:ed|ing|s)?", re.I)
CHINESE = re.compile(r"[链鏈][接結结]|[链鏈鍊]|[连連][接結结]|[连連]")
OTHER_SPELLINGS = (
    ("chaî", 7.0),
    ("체인", 5.0),
    ("リンク", 1.8),
)


def response(old, new):
    before = old.decode("utf-8", "ignore")
    text = (old + new).decode("utf-8", "ignore")
    boundary = len(before)
    token = text[boundary:]

    for m in CHINESE.finditer(text):
        if m.end() <= boundary:
            continue
        word = m.group()
        split = m.start() < boundary
        if word[0] in "链鏈鍊":
            if len(word) == 2 and split:
                return 6.8
            if len(token.strip()) == 1:
                return 7.8 if len(new) < 3 else 6.7
            if token.strip() in ("链接", "鏈接"):
                return 8.0
            if token.strip() in ("产业链", "產業鏈"):
                return 5.0
            if len(token.strip()) > 2:
                return 1.1
            return 2.1
        if len(word) == 2:
            if split:
                return 5.8 if token.strip() == word[-1] else 1.0
            return 3.2
        return 0.65 if token.strip() in "连連" else 0.0

    for m in ENGLISH.finditer(text):
        if m.end() <= boundary:
            continue
        word = m.group().lower()
        lead = text[:m.start()].lower()
        split = m.start() < boundary
        # Bundled compounds (blockchain, LinkedList, etc.) are mostly quiet.
        if re.match(r"[a-z]", text[m.end():], re.I):
            return 0.05
        if not split and re.search(r"[a-z]", text[boundary:m.start()], re.I):
            return 0.05
        if word.startswith("chain"):
            if split:
                if before.lower().endswith("chain"):
                    return 0.3
                return 9.0
            if word == "chained":
                return 5.8
            if word == "chaining":
                return 4.2
            if lead.endswith("-"):
                return 5.5
            if re.search(r"\b(?:supply|value)\s*$", lead):
                return 1.7
            if re.search(
                r"\b(?:side|light|heavy|straight|branched|long|cold)\s*$", lead
            ):
                return 4.6
            if word == "chains":
                return 3.6 if token[:1].isspace() else 2.3
            if token[:1].isspace():
                return 3.0
            return 3.3 if m.group()[0].isupper() else 4.2
        if split:
            return 0.3 if before.lower().endswith("link") else 0.8
        if lead.endswith("chain"):
            return 4.9
        if re.search(r"(?:cross|back)[- ]?$", lead):
            return 3.4
        if lead.endswith("<"):
            return 0.05
        if m.group().isupper():
            return 2.1
        if word == "linked":
            return 1.0
        if word == "linking":
            return 0.6
        if word == "links":
            return 1.25 if token[:1].isspace() else 0.6
        return 0.5 if token[:1].isspace() else 0.9

    # Other lexical forms of chain/link seen in the same role.
    for spelling, value in OTHER_SPELLINGS:
        at = text.rfind(spelling)
        if at >= 0 and at + len(spelling) > boundary:
            return value
    if token.strip().lower() == "href":
        return -2.5 if re.search(r"<link\s*$", before, re.I) else -0.3
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else b""
    new = prefix.token_bytes[-1]
    return (doc, (old + new)[-96:]), response(old, new)

programs.haiku:
"""Stretched-sound marks in casual Japanese.

The component fires on the marks that draw out a sound in chatty, spoken-style
text: the long-vowel mark ー after a hiragana (ありがとー, いやーー), the wave
dash 〜 / ～ / ~ after kana or kanji (元気だぜ〜), and a few casual sentence-final
particles (ね, よ, あ, へ). It stays silent on ー inside katakana loanwords
(ベビーカー), on dashes in number ranges (１〜２), and on ordinary text. A double
hyphen glued to a word inside code or a file listing (-rw-r--r--, day--x) fires too.

The program keeps no state. For each token it looks at the token itself and the
kind of character just before it, and returns a fixed size for that pair.
"""

READS = ()

HIRAGANA = set("ぁあぃいぅうぇえぉおかがきぎくぐけげこごさざしじすずせぜそぞただちぢっつづてでとどなにぬねのはばぱひびぴふぶぷへべぺほぼぽまみむめもゃやゅゆょよらりるれろわゐゑをん")


# Casual sentence-final particles and tone markers; typical activation after kana or kanji.
PARTICLES = {
    "ね": 4.6, "ねぇ": 6.0, "なぁ": 4.5, "よ": 3.0, "よね": 2.5, "ですね": 3.0, "ですよね": 3.0,
    "ですよ": 1.5, "あ": 3.5, "へ": 4.5, "ゆ": 3.0, "なんです": 3.0, "あと": 3.0, "♪": 2.0,
}


def char_kind(ch):
    """Rough script of one character: hiragana, katakana, kanji, digit, latin, other."""
    if not ch or ch == "�":
        return ""
    if ch in HIRAGANA:
        return "hiragana"
    if "゠" <= ch <= "ヿ" or "ｦ" <= ch <= "ﾟ":
        return "katakana"
    if "一" <= ch <= "鿿":
        return "kanji"
    if ch.isdigit():
        return "digit"
    if ch.isascii() and ch.isalpha():
        return "latin"
    return "other"


def step(carry, prefix, upstream):
    mark = prefix.token_strings[-1]
    if len(prefix) > 1:
        before = prefix.token_strings[-2]
        kind = char_kind(before[-1:])
    else:
        before, kind = "", ""
    if mark == "ー":  # long-vowel mark: stretched after kana, not in loanwords
        value = {"hiragana": 9.7, "kanji": 4.6}.get(kind, 0.0)
    elif mark in ("〜", "～"):  # wave dash
        value = {"hiragana": 12.0, "kanji": 5.0, "katakana": 9.0, "digit": 2.0}.get(kind, 4.0)
    elif mark == "~":
        value = 3.5 if kind == "kanji" else 0.0
    elif mark == "ـ":  # Arabic tatweel, the same stretching idea
        value = 5.5
    elif mark in PARTICLES and kind in ("hiragana", "kanji"):
        value = PARTICLES[mark]
    elif mark == "--":  # double hyphen glued to a word, as in file listings and CSS names
        glued = bool(before) and not before[-1:].isspace()
        if glued and kind == "latin":
            value = 5.0 if before.endswith(("r", "y")) else 2.0
        else:
            value = 0.0
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""A placeholder / exercise-prompt approximation, not a general word lookup.

Negative pulses mark NAME_ anonymization, underscore answer blanks, second-
person questions and answer requests, mathematical quantity phrases, follow-up
explanations, and date fields. First tokens and ordinary "why" get positive
offsets; unmatched tokens get a small baseline. Only a short recent-text buffer is retained;
it and the previous token reset at every document boundary.
"""
import re
from functools import lru_cache
import wordnet

READS = ()

# Presenting an answer, rather than an arbitrary set of individual token IDs.
ANSWER_VERBS = set('''write explain show give state describe document express
justify support discuss demonstrate prove illustrate present provide report
tell'''.split())
QUANTITIES = set('''value sum product probability area length perimeter volume
ratio number equation size ph angle height width distance'''.split())
DIMENSIONS = {'coordinate', 'dimension', 'measure'}
REQUEST = re.compile(r'\b(find|determine|calculate|compute|evaluate|identify|'
                     r'what is|what are|how much|how many)\b', re.I)


@lru_cache(maxsize=8192)
def forms(word):
    return set(wordnet.base_forms(word)) | {word}


@lru_cache(maxsize=8192)
def verb(word):
    return 'verb' in wordnet.parts_of_speech(word)


def predict(token, previous, recent, first):
    text = token.strip()
    word, prev = text.lower(), previous.strip().lower()
    if text and set(text) == {'_'}:
        if text == '_' and previous.rstrip().endswith('NAME'):
            return -1.93
        continuation = (not token[:1].isspace() and
                        re.search(r'_{3,}$', recent))
        if len(text) >= 3 or continuation:
            if '\n' in token or '\r' in token:
                return -0.15
            return -3.3 if previous.rstrip().endswith(':') else -1.25
    if first:
        if not text:
            return 0.05
        if token.startswith(('<|', '</')):
            return 0.10
        if text.isascii() and text.isalpha():
            if verb(word):
                return 0.42
            return 0.31 if text[0].isupper() else 0.21
        return 0.19
    if word == 'your':
        if forms(prev) & ANSWER_VERBS:
            return -1.21
        if forms(prev) & {'choose', 'select', 'test'}:
            return -0.74
        return 0.03
    if word == 'you':
        if prev == 'do':
            return -0.39
        return -0.08 if prev in {'would', 'can', 'could', 'will', 'did'} else 0.018
    if word == 'of':
        requested = bool(REQUEST.search(recent[-95:]))
        if forms(prev) & DIMENSIONS or prev.endswith('-coordinate'):
            return -2.2 if requested else -0.56
        if requested and forms(prev) & QUANTITIES:
            return -0.31
    if word in {'explain', 'describe', 'justify', 'prove'}:
        if '?' in previous:
            return -2.0
        if prev == 'please':
            return -0.81
        if previous.rstrip().endswith(('.', ',')) or prev == 'and':
            return -0.16
    if word == 'why':
        if prev == 'and':
            return -0.83
        if '?' in previous or forms(prev) & ANSWER_VERBS:
            return -0.35
        return 0.19
    if word == 'date' and text[:1].isupper():
        if prev in {'created', 'name', 'date'}:
            return -3.12
        if '\n' in previous or previous.endswith('['):
            return -0.42
    if word == 'area' and prev == 'surface':
        return -0.75
    if word == 'length' and prev == 'side':
        return -0.78
    if word == 'between' and prev in {'relationship', 'relation'}:
        if REQUEST.search(recent[-95:]) or 'explain' in recent.lower():
            return -0.49
    return 0.005


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry[0] != document
    previous, recent = ('', '') if first else carry[1:]
    token = prefix.token_strings[-1]
    value = predict(token, previous, recent, first)
    return (document, token, (recent + token)[-140:]), value
